window.HEXAPLA_DATA=window.HEXAPLA_DATA||{};window.HEXAPLA_DATA["Micah"]={"book":"Micah","vol":2,"source":{"title":"Frederick Field, Origenis Hexaplorum quae supersunt, II (Oxford 1875)","url":"https://archive.org/details/origenhexapla02unknuoft","license":"public domain"},"verses":{"1:1":[{"s":0,"e":3,"h":"דְּבַר־יְהוָֹה אֲשֶׁר הָיָה","l":"","t":"Ο΄. καὶ ἐγένετο λόγος κυρίου. Alia exempl. λόγος κυρίου ὃς ἐγένετο.^1 Ἀ. ῥῆμα κυρίου … Σ. Θ. ὡς οἱ Ο΄.^2","leaf":"1004","pg":"[988]","fn":["1004.1.1","1004.1.2"],"field":"1:1"},{"s":6,"e":6,"h":"הַמֹּרַשְׁתִּי","l":"Morasthaeum.","t":"Ο΄. τὸν τοῦ Μωρασθεί (s. Μωραθεί). Alia exempl. τὸν Μωραθίτην.^3","leaf":"1004","pg":"[988]","fn":["1004.1.3"],"field":"1:1"}],"1:2":[{"s":10,"e":10,"h":"לְעֵד","l":"In testem.","t":"Ο΄. εἰς μαρτύριον. Ἄλλος· εἰς μάρτυρα.^4 Σ. διαμαρτυρόμενος.^5","leaf":"1004","pg":"[988]","fn":["1004.1.4","1004.1.5"],"field":"1:2"}],"1:4":[{"s":0,"e":0,"h":"וְנָמַסּוּ","l":"Et liquefient.","t":"Ο΄. καὶ σαλευθήσεται. Ἀ. καὶ τακήσονται. Θ. καὶ ἐκτακήσονται (s. κατατακήσονται).^6","leaf":"1004","pg":"[988]","fn":["1004.1.6"],"field":"1:4"}],"1:5":[{"s":12,"e":13,"h":"וּמִי בָּמוֹת","l":"Et quaenam sunt excelsa.","t":"Ο΄. καὶ τίς ἡ ἁμαρτία. Σ. τίνα τὰ ὑψηλά.^7","leaf":"1004","pg":"[988]","fn":["1004.1.7"],"field":"1:5"}],"1:6":[{"s":2,"e":2,"h":"לְעִי","l":"In acervum lapidum.","t":"Ο΄. εἰς ὀπωροφυλάκιον. Ἀ. εἰς σωρούς. Σ. Θ. εἰς βουνούς.^8","leaf":"1004","pg":"[988]","fn":["1004.1.8"],"field":"1:6"}],"1:8":[{"s":10,"e":10,"h":"כַּתַּנִּים","l":"Sicut canes feri.","t":"Ο΄. ὡς δρακόντων (Ἀ. σειρήνων. Θ. λεόντων^9).","leaf":"1004","pg":"[988]","fn":["1004.1.9"],"field":"1:8"},{"s":12,"e":13,"h":"כִּבְנוֹת יַֽעֲנָה","l":"Sicut struthiones.","t":"Ο΄. ὡς θυγατέρων σειρήνων. Ἀ. Σ. (ὡς) στρουθοκαμήλων.^10","leaf":"1004","pg":"[988]","fn":["1004.1.10"],"field":"1:8"}],"1:9":[{"s":1,"e":1,"h":"אֲנוּשָׁה","l":"Desperata.","t":"Ο΄. κατεκράτησεν. Σ. Θ. βιαία.^11","leaf":"1004","pg":"[988]","fn":["1004.1.11"],"field":"1:9"}],"1:10":[{"s":0,"e":2,"h":"בְּגַת אַל־תַּגִּידוּ","l":"In Gath ne nuntietis.","t":"Ο΄. οἱ ἐν Γὲθ, μὴ μεγαλύνεσθε. Ἀ. Σ. οἱ ἐν Γὲθ, μὴ ἀναγγείλητε.^12","leaf":"1004","pg":"[988]","fn":["1004.1.12"],"field":"1:10"},{"s":3,"e":5,"h":"בָּכוֹ אַל־תִּבְכּוּ","l":"Flendo (s. In Acco) nolite flere.","t":"Ο΄. καὶ οἱ Ἐνακεὶμ (alia exempl. ἐν Βακεὶμ^13), μὴ ἀνοικοδομεῖτε. Ἀ. Σ. κλαυθμῷ μὴ κλαίετε. Θ. κλαυθμόν.^14","leaf":"1004","pg":"[988]","fn":["1004.1.13","1004.1.14"],"field":"1:10"},{"s":6,"e":7,"h":"בְּבֵית לְעַפְרָה","l":"In Beth-leaphra.","t":"Ο΄. ἐξ οἴκου κατὰ γέλωτα (potior scriptura καταγέλωτα^15). Ἀ. ἐν οἴκῳ χοός μου. Σ. _patera libatoria._ Θ. . Ὀφρά.^16","leaf":"1004","pg":"[988]","fn":["1004.1.15","1004.1.16"],"field":"1:10"}],"1:11":[{"s":0,"e":5,"h":"עִבְרִי לָכֶם יֹשֶׁבֶת שָׁפִיר עֶרְיָה־בֹשֶׁת","l":"Emigra vobis, habitatrix Saphir, nudata turpiter.","t":"Ο΄. κατὰ γέλωτα (καταγέλωτα) ὑμῶν. κατοικοῦσα καλῶς τὰς πόλεις αὐτῆς. Ἀ. διέρχεσθε ἑαυτοῖς, κατοικοῦσα Σαφείρ … Σ. διαβαίνετε ὑμῖν αἱ καθήμεναι καλῶς … Θ. … αἰσχυνομένη αἰσχύνῃ (.) ἡ πόλις αὕτη αἰσχύνη.^17","leaf":"1005","pg":"989","fn":["1005.0.17"],"field":"1:11"},{"s":6,"e":9,"h":"לֹא יָצְאָה יוֹשֶׁבֶת צַאֲנָן","l":"Non egressa est habitatrix Saanan.","t":"Ο΄. οὐκ ἐξῆλθε κατοικοῦσα Σενναάρ (alia exempl. Σεννάν^18). Ἀ. . ἡ καθημένη Σαναών (s. Σενάν).^19 Σ. οὐκ ἐξῆλθεν ἡ κατοικία εὐθηνοῦσα.^20 Θ. . ἡ κατοικοῦσα Σανιών.^21","leaf":"1005","pg":"989","fn":["1005.0.18","1005.0.19","1005.0.20","1005.0.21"],"field":"1:11"},{"s":10,"e":10,"h":"מִסְפַּד","l":"Planctus.","t":"Ο΄. κόψασθαι. Θ. εἰς κοπετόν.^22","leaf":"1005","pg":"989","fn":["1005.0.22"],"field":"1:11"},{"s":11,"e":12,"h":"בֵּית הָאֵצֶל","l":"Beth-esel.","t":"Ο΄. οἶκον ἐχόμενον αὐτῆς. Σ. . ἑξῆς.^23","leaf":"1005","pg":"989","fn":["1005.0.23"],"field":"1:11"}],"1:12":[{"s":0,"e":4,"h":"כִּי־חָלָה לְטוֹב יוֹשֶׁבֶת מָרוֹת","l":"Nam dolet propter bonum (ablatum) habitatrix Maroth.","t":"Ο΄. τίς ἤρξατο εἰς ἀγαθὰ κατοικούσῃ ὀδύνας; Ἀ. ὅτι ἠρρώστησεν εἰς ἀγαθὸν καθημένη Μαραώθ.^24 Σ. ὅτι ἐνόμισεν (ἤλπισεν ?) εἰς ἀγαθὸν ἡ κατοικοῦσα ἡ παραπικραίνουσα.^25 Θ. ἀναμένουσα εἰς ἀγαθὸν, κατοικοῦσα εἰς ὕψος.^26","leaf":"1005","pg":"989","fn":["1005.0.24","1005.0.25","1005.0.26"],"field":"1:12"}],"1:13":[{"s":5,"e":7,"h":"רֵאשִׁית חַטָּאת הִיא","l":"Principium (auctor) peccati illa est.","t":"Ο΄. ἀρχηγὸς ἁμαρτίας ※ Θ. αὕτη ↙ ἐστί.^27","leaf":"1005","pg":"989","fn":["1005.0.27"],"field":"1:13"}],"1:14":[{"s":0,"e":1,"h":"לָכֵן תִּתְּנִי","l":"Propterea dabis.","t":"Ο΄. διὰ τοῦτο δώσει (alia exempl. δώσεις^28). Ἀ. Σ. Θ. ὅτι δῶρα.^29","leaf":"1005","pg":"989","fn":["1005.0.28","1005.0.29"],"field":"1:14"},{"s":6,"e":7,"h":"בָּתֵּי אַכְזִיב","l":"Domus Achzib.","t":"Ο΄. οἴκους ματαίους (Ἀ. ψεύδους (s. ψεύσματος). Σ. Ἀχζίβ. Θ. ἐξ ἀνάγκης^30).","leaf":"1005","pg":"989","fn":["1005.0.30"],"field":"1:14"}],"1:15":[{"s":0,"e":10,"h":"עד הַיֹּרֵשׁ אָבִי לָךְ יוֹשֶׁבֶת מָרֵשָׁה עַד־עֲדֻלָּם יָבוֹא כְּבוֹד יִשְׂרָאֵל","l":"Adhuc heredem adducam tibi, habitatrix Maresae; usque ad Adullam veniet gloria (nobiles) Israelis.","t":"Ο΄. ἕως τοὺς","leaf":"1005","pg":"989","fn":[],"field":"1:15"},{"s":0,"e":10,"h":"עד הַיֹּרֵשׁ אָבִי לָךְ יוֹשֶׁבֶת מָרֵשָׁה עַד־עֲדֻלָּם יָבוֹא כְּבוֹד יִשְׂרָאֵל","l":"","t":"κληρονόμους (Ἀ. τὸν κληρόνομον^31) ἀγάγωσι (Ἀ. ὡς οἱ Ο΄. Σ. ἄξω καὶ σοί. Θ. ἄξω (s. ἀγάγω) σοί^32), κατοικοῦσα Λαχεὶς κληρονομία· ἕως Ὀδολλὰμ ἥξει ἡ δόξα ÷ τῆς θυγατρὸς ↙ Ἰσραήλ.^33 Σ. ἔτι κληρόνομον ἄξω καὶ σοὶ, κατοικία Μαρεσά· ἕως Ὀδολλὰμ ἥξει τῆς δόξης Ἰσραήλ.^34","leaf":"1006","pg":"990","fn":["1006.0.31","1006.0.32","1006.0.33","1006.0.34"],"field":"1:15","cont":true},{"s":10,"e":10,"h":"יִשְׂרָאֵל","l":"","t":"Ο΄. Ἰσραήλ. Alia exempl. Σιών.^35","leaf":"1006","pg":"990","fn":["1006.0.35"],"field":"1:15"}],"1:16":[{"s":6,"e":6,"h":"קָרְחָתֵךְ","l":"Calvitiem tuam.","t":"Ο΄. τὴν χηρείαν (alia exempl. ξύρησίν^36) σου. Ἀ. Σ. φαλάκρωσιν. Θ. _rasuram._^37","leaf":"1006","pg":"990","fn":["1006.0.36","1006.0.37"],"field":"1:16"}],"2:1":[{"s":0,"e":0,"h":"הוֹי","l":"Vae!","t":"Ο΄. ἐγένοντο. Ἀ. Σ. οὐαί.^1","leaf":"1006","pg":"990","fn":["1006.1.1"],"field":"2:1"},{"s":10,"e":13,"h":"כִּי יֶשׁ־לְאֵל יָדָם","l":"Quia est in potestate manus eorum.","t":"Ο΄. διότι οὐκ ἦραν πρὸς τὸν θεὸν χεῖρας αὐτῶν. Ἀ. ὅτι ἰσχυρὸν χεὶρ αὐτοῦ. Σ. ὅτι ἴσχυεν ἡ χεὶρ αὐτῶν. Θ. διότι ἔχουσιν ἰσχὺν τὴν χεῖρα αὐτῶν.^2","leaf":"1006","pg":"990","fn":["1006.1.2"],"field":"2:1"}],"2:2":[{"s":2,"e":2,"h":"וְגָזָלוּ","l":"Et rapiunt.","t":"Ο΄. καὶ διήρπαζον ÷ ὀρφανούς ↙. Οἱ λοιποί· καὶ ἐσυκοφάντουν.^3","leaf":"1006","pg":"990","fn":["1006.1.3"],"field":"2:2"},{"s":8,"e":8,"h":"וְאִישׁ","l":"","t":"Ο΄. ※ Ἀ. Σ. καὶ ↙ ἄνδρα.^4","leaf":"1006","pg":"990","fn":["1006.1.4"],"field":"2:2"}],"2:4":[{"s":14,"e":17,"h":"אֵיךְ יָמִישׁ לִי לְשׁוֹבֵב","l":"Quomodo subtrahit eam mihi! impiis (agros nostros distribuit).","t":"Ο΄. καὶ οὐκ ἦν ὁ κωλύων αὐτὸν τοῦ ἀποστρέψαι. Ἀ. πῶς ἀποδοθήσεταί μοι τοῖς γείτοσι; Σ. πῶς ἀναχωρήσει μοι τοῦ ἐπιστρέψαι; Θ. πῶς ἀνασαλεύσει αὐτὸν τοῦ ἐπιστρέψαι;^5","leaf":"1006","pg":"990","fn":["1006.1.5"],"field":"2:4"},{"s":19,"e":19,"h":"יְחַלֵּק","l":"Distribuit.","t":"Ο΄. διεμερίσθησαν. Ἀ. ἐν μερισμοῖς (s. διαμερισμοῖς, s. διαιρέσεσι). Θ. μεριεῖ (s. διαμεριεῖ, s. διελεῖ). Σ. ὁμοίως τοῖς Ο΄.^6","leaf":"1006","pg":"990","fn":["1006.1.6"],"field":"2:4"}],"2:6":[{"s":0,"e":8,"h":"אַל־תַּטִּפוּ יַטִּיפ֑וּן לֹא־יַטִּפוּ לָאֵלֶּה לֹא יִסַּג כְּלִמּוֹת","l":"Ne stilletis (vaticinemini), stillant (dictitant): at nisi stillaverint illis, non recedet ignominia.","t":"Ο΄. μὴ κλαίετε δάκρυσι, μηδὲ δακρυέτωσαν ἐπὶ τούτοις· οὐδὲ γὰρ ἀπώσεται ὀνείδη. Ἀ. μὴ σταλάζετε σταλάζοντες, οὐ σταλάζετε εἰς τούτους, οὐ καταλήψῃ ἐντροπὰς (ὁ λέγων).^7 Σ. μὴ ἐπιτιμᾶτε· ἐὰν ἐπιτιμήσητε, οὐκ ἐπιτιμῶν τε (fort. ἐπιτιμῶντες) τούτους, οὐ κωλύει καταισχυμμός.^8","leaf":"1006","pg":"990","fn":["1006.1.7","1006.1.8"],"field":"2:6"}],"2:7":[{"s":9,"e":14,"h":"הֲלוֹא דְבָרַי יֵיטִיבוּ עִם הַיָּשָׁר הוֹלֵךְ","l":"Nonne verba mea bona sunt cum eo qui recte vitam degit?","t":"Ο΄. οὐχ οἱ λόγοι αὐτοῦ εἰσι καλοὶ μετ’ αὐτοῦ, καὶ ὀρθοὶ πεπόρευνται; Ἀ. μήτι οὐ ῥήματά μου ἀγαθύνουσι μετ’ αὐτοῦ εὐθέως πορευομένου;^9 Σ. μὴ οὐ λόγοι μου ἀγαθοποιοῦσι τῷ ὀρθῶς ἀναστρεφομένῳ;^10","leaf":"1007","pg":"991","fn":["1007.0.9","1007.0.10"],"field":"2:7"}],"2:8":[{"s":0,"e":3,"h":"וְאֶתְמוּל עַמִּי לְאוֹיֵב יְקוֹמֵם","l":"Etiam dudum populus meus tanquam hostis insurrexit.","t":"Ο΄. καὶ ἔμπροσθεν ὁ λαός μου εἰς ἔχθραν ἀντέστη. Ἀ. καὶ συναντιῶ …^11 Σ. πρὸ μιᾶς δὲ ὁ λαός μου ὡς ἐχθρὸς ἀντέστη.^12","leaf":"1007","pg":"991","fn":["1007.0.11","1007.0.12"],"field":"2:8"},{"s":4,"e":11,"h":"מִמּוּל שַׂלְמָה אֶדֶר תַּפְשִׁטוּן מֵעֹבְרִים בֶּטַח שׁוּבֵי מִלְחָמָה","l":"A facie togae pallium detrahitis transeuntibus secure, alienis a bello.","t":"Ο΄. κατέναντι τῆς εἰρήνης αὐτοῦ· τὴν δορὰν ÷ αὐτοῦ ↙ ἐξέδειραν, τοῦ ἀφελέσθαι ἐλπίδας, συντριμμὸν πολέμου. Σ. ἀπὸ ἱματίων ἐνδυμάτων ἐξεδύσατε τοὺς ὁδοιποροῦντας ἀμερίμνως ἐκ πολέμου.^13","leaf":"1007","pg":"991","fn":["1007.0.13"],"field":"2:8"}],"2:10":[{"s":0,"e":0,"h":"קוּמוּ","l":"","t":"Ο΄. ἀνάστηθι. Οἱ λοιποί· ἀνάστητε.^14","leaf":"1007","pg":"991","fn":["1007.0.14"],"field":"2:10"}],"2:12":[{"s":10,"e":14,"h":"כְּצֹאן בָּצְרָה כְּעֵדֶר בְּתוֹךְ הַדָּבְרוֹ","l":"Sicut oves Bosrae, sicut gregem in medio caulae ejus.","t":"Ο΄. ὡς πρόβατα ἐν θλίψει, ὡς ποίμνιον ἐν μέσῳ κοίτης αὐτῶν. Ἀ. (ὡς) ποίμνιον _in rotundo_, ὡς ἀγέλη ἐν μέσῳ _congregationis suae._ Σ. Θ. ὡς βοσκήματα ἐν ὀχυρώματι, ὡς ἀγέλη ἐν μέσῳ τῆς ἐρήμου.^15","leaf":"1007","pg":"991","fn":["1007.0.15"],"field":"2:12"}],"2:13":[{"s":0,"e":1,"h":"עָלָה הַפֹּרֵץ","l":"Ascendit perruptor.","t":"Ο΄. διὰ τῆς διακοπῆς. Alia exempl. ἀνάβηθι διὰ τῆς διακοπῆς.^16 Ἀ. Θ. ἀνέβη . . Σ. ἀναβήσεται ὁ διακόπτων.^17","leaf":"1007","pg":"991","fn":["1007.0.16","1007.0.17"],"field":"2:13"}],"2:3":[{"s":21,"e":21,"h":"","l":"","t":"Cap. II. 3. ÷ ἐξαίφνης ↙.^18","leaf":"1007","pg":"991","fn":["1007.0.18"],"field":"2:3","gap":true}],"3:1":[{"s":5,"e":7,"h":"קְצִינֵי בֵּית יִשְׂרָאֵל","l":"Duces domus Israelis.","t":"Ο΄. καὶ οἱ κατάλοιποι οἴκου Ἰσραήλ. Ἀ. Θ. ἀρχὴ οἴκου . . Σ. ἡγούμενοι …^1","leaf":"1007","pg":"991","fn":["1007.1.1"],"field":"3:1"},{"s":8,"e":9,"h":"הֲלוֹא לָכֶם","l":"","t":"Ο΄. οὐχ ὑμῖν ἐστι. Σ. ἢ οὐχ ὑμῶν.^2","leaf":"1007","pg":"991","fn":["1007.1.2"],"field":"3:1"}],"3:4":[{"s":1,"e":1,"h":"יִזְעֲקוּ","l":"","t":"Ο΄. κεκράξονται. Ἀ. ὡς οἱ Ο΄. Σ. βοήσονται.^3","leaf":"1007","pg":"991","fn":["1007.1.3"],"field":"3:4"},{"s":7,"e":7,"h":"וְיַסְתֵּר","l":"Et abscondet.","t":"Ο΄. καὶ ἀποστρέψει. Σ. ἀλλὰ ἀποκρύψει.^4","leaf":"1007","pg":"991","fn":["1007.1.4"],"field":"3:4"},{"s":13,"e":14,"h":"הֵרֵעוּ מַעַלְלֵיהֶם","l":"Mala fecerunt opera eorum.","t":"Ο΄. ἐπονηρεύσαντο ἐν τοῖς ἐπιτηδεύμασιν αὐτῶν ÷ ἐπ’ αὐτούς ↙.^5 Ἀ. ἐκάκωσαν τὰ ἐπιτηδεύ-","leaf":"1007","pg":"991","fn":["1007.1.5"],"field":"3:4"},{"s":13,"e":14,"h":"הֵרֵעוּ מַעַלְלֵיהֶם","l":"","t":"ματα αὐτῶν. Σ. ἐπονηρεύσαντο διὰ τῶν ἐπιτηδευμάτων. Θ. ἐπονηρεύσαντο περὶ (s. ἕνεκεν) τῶν ἐπιτηδευμάτων αὐτῶν.^6","leaf":"1008","pg":"992","fn":["1008.0.6"],"field":"3:4","cont":true}],"3:5":[{"s":12,"e":19,"h":"וַאֲשֶׁר לֹא־יִתֵּן עַל־פִּיהֶם וְקִדְּשׁוּ עָלָיו מִלְחָמָה","l":"Et si quis non dederit in ore eorum quippiam, consecrant (parant) contra eum bellum.","t":"Ο΄. καὶ οὐκ ἐδόθη εἰς τὸ στόμα αὐτῶν, ἤγειραν (alia exempl. ἡγίασαν^7) ἐπ’ αὐτὸν πόλεμον. Ἀ. Θ. καὶ οὐκ ἔδωκαν ἐπὶ τὸ στόμα αὐτῶν, ἡγίασαν ἐπ’ αὐτὸν πόλεμον. Σ. ἐπὶ δὲ τοὺς μὴ δίδοντας (s. κατὰ δὲ τῶν μὴ διδόντων) εἰς τὸ στόμα αὐτῶν _cogitabant_ πολέμους.^8","leaf":"1008","pg":"992","fn":["1008.0.7","1008.0.8"],"field":"3:5"}],"3:6":[{"s":3,"e":3,"h":"מֵחָזוֹן","l":"A visione (ne amplius visiones videatis).","t":"Ο΄. ἐξ ὁράσεως. Σ. ὥστε μὴ ὁρᾶν ὑμᾶς.^9","leaf":"1008","pg":"992","fn":["1008.0.9"],"field":"3:6"},{"s":6,"e":6,"h":"מִקְּסֹם","l":"A divinatione.","t":"Ο΄. ἐκ μαντείας. Σ. ὥστε μὴ μαντεύεσθαι ὑμᾶς.^10","leaf":"1008","pg":"992","fn":["1008.0.10"],"field":"3:6"}],"3:7":[{"s":4,"e":7,"h":"וְעָטוּ עַל־שָׂפָם כֻּלָּם","l":"Et obvelabunt mystacem omnes illi.","t":"Ο΄. καὶ καταλαλήσουσι κατ’ αὐτῶν πάντες αὐτοί. Σ. καὶ περιβαλοῦνται ἐπὶ τῶν χειλέων αὐτῶν πάντες.^11","leaf":"1008","pg":"992","fn":["1008.0.11"],"field":"3:7"},{"s":8,"e":11,"h":"כִּי אֵין מַעֲנֵה אֱלֹהִים","l":"Quia non est responsum Dei.","t":"Ο΄. διότι οὐκ ἔσται ὁ ἐπακούων αὐτῶν. Θ. διότι οὐκ ἔστιν ἀπόκρισις Ἐλωείμ.^12 Σ. διότι οὐκ ἦν ἀπόκρισις τοῦ θεοῦ.^13","leaf":"1008","pg":"992","fn":["1008.0.12","1008.0.13"],"field":"3:7"},{"s":11,"e":11,"h":"","l":"","t":"Cap. III. 7. ÷ τὰ ἐνύπνια ↙.^23","leaf":"1008","pg":"992","fn":["1008.0.23"],"field":"3:7","gap":true}],"3:8":[{"s":0,"e":8,"h":"וְאוּלָם אָנֹכִי מָלֵאתִי כֹחַ אֶת־רוּחַ יְהוָֹה וּמִשְׁפָּט וּגְבוּרָה","l":"Verumtamen ego repletus sum virtute cum spiritu Dei, et judicio, et fortitudine.","t":"Ο΄. ἐὰν μὴ ἐγὼ ἐμπλήσω ἰσχὺν (alia exempl. ἀλλὰ μὴν ἐγὼ ἐνεπλήσθην ἰσχύος^14) ἐν πνεύματι κυρίου, καὶ κρίματος, καὶ δυναστείας. Σ. ἀλλὰ μὴν ἐγὼ ἐνεπλήσθην ἰσχύος πνεύματος καὶ κρίματος καὶ δυναστείας.^15 Θ. ἐκωλύθη (s. συνεσχέθη), ἐγώ εἰμι ἐνεπλήσθην ἰσχύος, πνεύματος …^16","leaf":"1008","pg":"992","fn":["1008.0.14","1008.0.15","1008.0.16"],"field":"3:8"}],"3:9":[{"s":6,"e":6,"h":"קְצִינֵי","l":"Duces.","t":"Ο΄. οἱ κατάλοιποι. Ἀ. Θ. οἱ ἐξουσιάζοντες (s. δυναστεύοντες).^17","leaf":"1008","pg":"992","fn":["1008.0.17"],"field":"3:9"}],"3:11":[{"s":5,"e":5,"h":"יוֹרוּ","l":"Docent.","t":"Ο΄. ἀπεκρίνοντο. Ἀ. Θ. ἐφώτιζον.^18","leaf":"1008","pg":"992","fn":["1008.0.18"],"field":"3:11"},{"s":6,"e":6,"h":"וּנְבִיאֶיהָ","l":"","t":"Ο΄. καὶ οἱ προφῆται ※ Οἱ Γ΄. αὐτῆς ↙.^19","leaf":"1008","pg":"992","fn":["1008.0.19"],"field":"3:11"}],"3:12":[{"s":0,"e":7,"h":"לָכֵן בִּגְלַלְכֶם צִיּוֹן שָׂדֶה תֵחָרֵשׁ וִירוּשָׁלַםִ עִיִּין תִּהְיֶה","l":"Propterea vestri causa Sion ut ager arabitur, et Jerusalem rudera fiet.","t":"Ο΄. διὰ τοῦτο δι’ ὑμᾶς Σιὼν ὡς ἀγρὸς ἀροτριαθήσεται, καὶ Ἱερουσαλὴμ ὡς ὀπωροφυλάκιον (Ἀ. ὡς σωρός (s. λιθολογία). Σ. βουνοί. Θ. εἰς ἐρήμωσιν^20) ἔσται. Ἀ. διὰ τοῦτο χάριν ὑμῶν Σιὼν χώρα ἀροτριαθήσεται, καὶ Ἱερουσαλὴμ λιθολογηθήσεται.^21","leaf":"1008","pg":"992","fn":["1008.0.20","1008.0.21"],"field":"3:12"},{"s":10,"e":11,"h":"לְבָמוֹת יָעַר","l":"In excelsa silvae.","t":"Ο΄. εἰς ἄλσος δρυμοῦ. Σ. εἰς ὕψος δρυμοῦ. Θ. εἰς βουνὸν δρυμοῦ.^22","leaf":"1008","pg":"992","fn":["1008.0.22"],"field":"3:12"}],"4:1":[{"s":5,"e":6,"h":"בֵּית־יְהוָֹה","l":"","t":"Ο΄. κυρίου. Alia exempl. τοῦ οἴκου κυρίου.^1 Οἱ Γ΄. θεοῦ.^2","leaf":"1009","pg":"993","fn":["1009.1.1","1009.1.2"],"field":"4:1"},{"s":13,"e":13,"h":"וְנָהֲרוּ","l":"Et confluent.","t":"Ο΄. καὶ σπεύσουσι. Σ. καὶ συναχθήσονται.^3","leaf":"1009","pg":"993","fn":["1009.1.3"],"field":"4:1"}],"4:2":[{"s":17,"e":18,"h":"כִּי מִצִּיּוֹן","l":"","t":"Ο΄. ὅτι ἐκ Σιών. Σ. ἐκ Σιὼν γάρ.^4","leaf":"1009","pg":"993","fn":["1009.1.4"],"field":"4:2"}],"4:3":[{"s":1,"e":1,"h":"בֵּין","l":"","t":"Ο΄. ἀναμέσον. Ἀ. Σ. μεταξύ.^5","leaf":"1009","pg":"993","fn":["1009.1.5"],"field":"4:3"},{"s":12,"e":12,"h":"וַחֲנִיתֹתֵיהֶם","l":"Et hastas suas.","t":"Ο΄. καὶ τὰ δόρατα (alia exempl. τὰς ζιβύνας^6) αὐτῶν","leaf":"1009","pg":"993","fn":["1009.1.6"],"field":"4:3"},{"s":17,"e":18,"h":"אֶל־גּוֹי","l":"","t":"Ο΄. ἐπ’ ἔθνος. Aliter: Ο΄. πρὸς ἔθνος. Σ. Θ. ἐπ’ ἔθνος.^7","leaf":"1009","pg":"993","fn":["1009.1.7"],"field":"4:3"}],"4:4":[{"s":4,"e":5,"h":"וְתַחַת תְּאֵנָתוֹ","l":"Et sub ficu sua.","t":"Ο΄. καὶ ἕκαστος ※ Ἀ. Θ. ὑποκάτω ↙ συκῆς αὐτοῦ.^8","leaf":"1009","pg":"993","fn":["1009.1.8"],"field":"4:4"}],"4:5":[{"s":5,"e":6,"h":"בְּשֵׁם אֱלֹהָיו","l":"","t":"Ο΄. τὴν ὁδὸν αὐτοῦ. Ἄλλος· ἐν ὀνόματι θεοῦ (αὐτοῦ).^9","leaf":"1009","pg":"993","fn":["1009.1.9"],"field":"4:5"}],"4:7":[{"s":3,"e":3,"h":"לִשְׁאֵרִית","l":"In reliquias.","t":"Ο΄. εἰς ὑπόλειμμα ÷ διαμένον ↙.^10","leaf":"1009","pg":"993","fn":["1009.1.10"],"field":"4:7"}],"4:8":[{"s":3,"e":3,"h":"עֹפֶל","l":"Clivus.","t":"Ο΄. αὐχμώδης. Ἀ. σκοτώδης. Σ. ἀπόκρυφος.^11","leaf":"1009","pg":"993","fn":["1009.1.11"],"field":"4:8"},{"s":4,"e":5,"h":"בַּת־צִיּוֹן","l":"Filiae Sionis.","t":"Ο΄. Σ. θυγάτηρ Σιών.^12","leaf":"1009","pg":"993","fn":["1009.1.12"],"field":"4:8"},{"s":6,"e":6,"h":"עָדֶיךָ","l":"Ad te.","t":"Ο΄. ἐπὶ σέ. Ἀ. ἕως . . Θ. ἐπὶ σέ.^13","leaf":"1009","pg":"993","fn":["1009.1.13"],"field":"4:8"},{"s":11,"e":11,"h":"מַמְלֶכֶת","l":"Regnum.","t":"Ο΄. βασιλεία ÷ ἐκ Βαβυλῶνος ↙.^14","leaf":"1009","pg":"993","fn":["1009.1.14"],"field":"4:8"}],"4:9":[{"s":2,"e":3,"h":"תָרִיעִי רֵעַ","l":"Clamores (lugubres) edis.","t":"Ο΄. ἔγνως κακά. Ἀ. ἐκάκωσας . .^15","leaf":"1009","pg":"993","fn":["1009.1.15"],"field":"4:9"},{"s":5,"e":6,"h":"אֵין־בָּךְ","l":"","t":"Ο΄. οὐκ ἦν σοι. Οἱ λοιποί· οὐκ ἔστι σοι.^16","leaf":"1009","pg":"993","fn":["1009.1.16"],"field":"4:9"},{"s":8,"e":8,"h":"יוֹעֲצֵךְ","l":"Consiliarius tuus.","t":"Ο΄. ἡ βουλή σου. Ἄλλος· ὁ σύμβουλός σου.^17","leaf":"1009","pg":"993","fn":["1009.1.17"],"field":"4:9"}],"4:10":[{"s":1,"e":1,"h":"וָגֹחִי","l":"Et enitere.","t":"Ο΄. καὶ ἀνδρίζου, ÷ καὶ ἔγγιζε ↙.^18 Ἄλλος· διατείνου.^19","leaf":"1009","pg":"993","fn":["1009.1.18","1009.1.19"],"field":"4:10"},{"s":20,"e":20,"h":"","l":"","t":"Cap. IV. 10. κύριος ÷ ὁ θεός σου ↙.^28","leaf":"1010","pg":"994","fn":["1010.0.28"],"field":"4:10","gap":true}],"4:11":[{"s":1,"e":1,"h":"נֶאֶסְפוּ","l":"Congregatae sunt.","t":"Ο΄. ἐπισυνήχθησαν. Alia exempl. ἐπισυναχθήσεται.^20 (Ἀ.) συνελέγησαν. Σ. συναχθήσεται.^21","leaf":"1009","pg":"993","fn":["1009.1.20","1009.1.21"],"field":"4:11"},{"s":6,"e":6,"h":"תֶּחֱנָף","l":"Polluatur.","t":"Ο΄. ἐπιχαρούμεθα. Ἀ. _incidet in furorem._ Σ. κατακριθήσεται (s. καταδικασθήσεται).^22","leaf":"1009","pg":"993","fn":["1009.1.22"],"field":"4:11"}],"4:12":[{"s":10,"e":10,"h":"כֶּעָמִיר","l":"Sicut manipulos.","t":"Ο΄. ὡς δράγματα. Ἀ. Σ. ὡς ἄχνη. Θ. ὡς καλάμη.^23","leaf":"1010","pg":"994","fn":["1010.0.23"],"field":"4:12"}],"4:13":[{"s":11,"e":13,"h":"וַהֲדִקּוֹת עַמִּים רַבִּים","l":"Et comminues populos multos.","t":"Ο΄. καὶ κατατήξεις (alia exempl. λεπτυνεῖς^24) λαοὺς πολλούς. Alia exempl. ÷ καὶ κατατήξεις ἐν αὐτοῖς ἔθνη ↙, καὶ λεπτυνεῖς λαοὺς πολλούς.^25","leaf":"1010","pg":"994","fn":["1010.0.24","1010.0.25"],"field":"4:13"},{"s":14,"e":14,"h":"וְהַחֲרַמְתִּי","l":"Et devovebo.","t":"Ο΄. καὶ ἀναθήσεις. Οἱ λοιποί· ἀναθηματίσεις.^26","leaf":"1010","pg":"994","fn":["1010.0.26"],"field":"4:13"},{"s":16,"e":16,"h":"בִּצְעָם","l":"Quaestum eorum.","t":"Ο΄. τὸ πλῆθος αὐτῶν. Σ. τὸ κέρδος αὐτῶν. Θ. τὰ δῶρα αὐτῶν. Ε΄. τὴν ὠφέλειαν . .^27","leaf":"1010","pg":"994","fn":["1010.0.27"],"field":"4:13"}],"4:14":[{"s":0,"e":3,"h":"עַתָּה תִּתְגֹּדְדִי בַת־גְּדוּד","l":"Nunc turmatim congrega te, filia turmae.","t":"Ο΄. νῦν ἐμφραχθήσεται θυγάτηρ ἐμφραγμῷ. Σ. νῦν ὠδινήσουσί σε, θύγατερ συνεχομένη (s. πολιορκουμένη).^1 Aliter: Ἀ. Σ. Θ. Ε΄. _Nunc vastaberis, filia latronis._^2","leaf":"1010","pg":"994","fn":["1010.1.1","1010.1.2"],"field":"5:1"},{"s":4,"e":6,"h":"מָצוֹר שָׂם עָלֵינוּ","l":"Obsidionem ponit contra nos.","t":"Ο΄. συνοχὴν ἔταξεν ἐφ’ ἡμᾶς. Σ. συνοχὴ (s. πολιορκία) ἐτέθη ἐφ’ ἡμᾶς.^3","leaf":"1010","pg":"994","fn":["1010.1.3"],"field":"5:1"},{"s":7,"e":13,"h":"בַּשֵּׁבֶט יַכּוּ עַל־הַלְּחִי אֵת שֹׁפֵט יִשְׂרָאֵל","l":"Virga percutient super maxillam judicem Israelis.","t":"Ο΄. ἐν ῥάβδῳ πατάξουσιν ἐπὶ σιαγόνα τὰς φυλὰς (Οἱ Γ΄. τὸν κριτὴν^4) τοῦ Ἰσραήλ. Ἀ. . πλήξουσιν ἐπὶ σιαγόνα τὸν κριτὴν Ἰσραήλ. Σ. ῥάβδῳ τύψουσι κατὰ σιαγόνας τὸν κριτὴν Ἰσραήλ. Θ. . πατάξει ἐπὶ σιαγόνα τὸν κριτὴν Ἰσραήλ.^5","leaf":"1010","pg":"994","fn":["1010.1.4","1010.1.5"],"field":"5:1"}],"5:1":[{"s":4,"e":4,"h":"צָעִיר","l":"Parvus es.","t":"Ο΄. ὀλιγοστὸς εἶ. Alia exempl. μὴ ὀλιγοστὸς εἶ;^6","leaf":"1010","pg":"994","fn":["1010.1.6"],"field":"5:2"}],"5:2":[{"s":4,"e":4,"h":"יוֹלֵדָה","l":"Quae paritura est.","t":"Ο΄. τικτούσης. Σ. αὐτῆς δὲ τικτούσης. Θ. ἔτεκε.^7","leaf":"1010","pg":"994","fn":["1010.1.7"],"field":"5:3"},{"s":7,"e":7,"h":"אֶחָיו","l":"","t":"Ο΄. τῶν ἀδελφῶν αὐτῶν (Ἀ. Σ. Θ. αὐτοῦ^8).","leaf":"1010","pg":"994","fn":["1010.1.8"],"field":"5:3"}],"5:3":[{"s":0,"e":1,"h":"וְעָמַד וְרָעָה","l":"Et stabit, et pascet.","t":"Ο΄. καὶ στήσεται, ÷ καὶ ὄψεται ↙, καὶ ποιμανεῖ ÷ τὸ ποίμνιον αὐτοῦ ↙.^9","leaf":"1010","pg":"994","fn":["1010.1.9"],"field":"5:4"},{"s":8,"e":8,"h":"וְיָשָׁבוּ","l":"Et habitabunt.","t":"Ο΄. ὑπάρξουσιν. Σ. καὶ κατοικήσουσι.^10","leaf":"1010","pg":"994","fn":["1010.1.10"],"field":"5:4"},{"s":9,"e":14,"h":"כִּי־עַתָּה יִגְדַּל עַד־אַפְסֵי־אָרֶץ","l":"Nam nunc magnus erit usque ad terminos terrae.","t":"Ο΄. διότι νῦν μεγαλυνθήσονται ἕως ἄκρων τῆς γῆς. Σ. τότε γὰρ μεγαλυνθήσεται ἕως ἐσχάτου τῆς γῆς.^11","leaf":"1010","pg":"994","fn":["1010.1.11"],"field":"5:4"},{"s":9,"e":14,"h":"כִּי־עַתָּה יִגְדַּל עַד־אַפְסֵי־אָרֶץ","l":"","t":"Ο΄. ἑπτὰ ποιμένες, καὶ ὀκτὼ δήγματα (Θ. Ε΄. _principes_) ἀνθρώπων. Ἀ. ἑπτὰ νομεῖς, καὶ ὀκτὼ καθεσταμένους ἀνθρώπους. Σ. ἑπτὰ ποιμένας, καὶ ὀκτὼ χριστοὺς ἀνθρώπων. Θ. ἑπτὰ ποιμένας, καὶ ὀκτὼ ἀρχηγοὺς ἀνθρώπων.^12","leaf":"1011","pg":"995","fn":["1011.0.12"],"field":"5:4","cont":true}],"5:4":[{"s":12,"e":16,"h":"שִׁבְעָה רֹעִים וּשְׁמֹנָה נְסִיכֵי אָדָם","l":"Septem pastores, et octo unctos (principes) hominum.","t":"","leaf":"1010","pg":"994","fn":[],"field":"5:5"}],"5:5":[{"s":0,"e":8,"h":"וְרָעוּ אֶת־אֶרֶץ אַשּׁוּר בַּחֶרֶב וְאֶת־אֶרֶץ נִמְרֹד בִּפְתָחֶיהָ","l":"Et pascent terram Assyriae gladio, et terram Nimrod in portis ejus.","t":"Ο΄. καὶ ποιμανοῦσι τὸν Ἀσσοὺρ ἐν ῥομφαίᾳ, καὶ τὴν γῆν τοῦ Νεβρὼδ ἐν τῇ τάφρῳ αὐτῆς (Ἀ. ἐν ζιβύναις (s. σειρομάσταις) αὐτῆς. Σ. ἐντὸς πυλῶν αὐτῆς. Θ. ἐν πύλαις αὐτῶν. Ε΄. ἐν παραξιφίσιν αὐτῶν^13). Σ. _Et pascent terram Assur in gladio, et regionem Nemrod intra portas ejus._^14","leaf":"1011","pg":"995","fn":["1011.0.13","1011.0.14"],"field":"5:6"},{"s":9,"e":9,"h":"וְהִצִּיל","l":"","t":"Ο΄. καὶ ῥύσεται. Aliud exempl. καὶ τὴν εὐσέβειαν ἐν τῇ τάφρῳ ῥύσεται.^15","leaf":"1011","pg":"995","fn":["1011.0.15"],"field":"5:6"}],"5:6":[{"s":9,"e":11,"h":"כִּרְבִיבִים עֲלֵי־עֵשֶׂב","l":"Sicut imbres super herbam.","t":"Ο΄. καὶ ὡς ἄρνες ἐπὶ ἄγρωστιν. Ἀ. καὶ ὡς ψεκάδες ἐπὶ πόαν. Σ. Θ. καὶ ὡσεὶ νιφετὸς ἐπὶ χόρτον.^16","leaf":"1011","pg":"995","fn":["1011.0.16"],"field":"5:7"},{"s":12,"e":19,"h":"אֲשֶׁר לֹא־יְקַוֶּה לְאִישׁ וְלֹא יְיַחֵל לִבְנֵי אָדָם","l":"Quae non exspectat virum, nec praestolatur filios hominis.","t":"Ο΄. ὅπως μὴ συναχθῇ μηδεὶς, μηδὲ ὑποστῇ ἐν υἱοῖς ἀνθρώπων. Ἀ. ὃς οὐχ ὑπομενεῖ ἄνδρα, καὶ οὐ περιμενεῖ υἱοὺς ἀνθρώπων. Θ. ὃς οὐ μενεῖ ἄνθρωπον, καὶ οὐκ ἐλπίσει ἐπὶ υἱὸν ἀνθρώπου.^17 Οἱ Γ΄. ὃς οὐ πεποιθήσει ἐπ’ ἄνθρωπον, καὶ οὐ περιμενεῖ (s. προσδοκήσει, s. προσδέξεται) υἱὸν ἀνθρώπου.^18","leaf":"1011","pg":"995","fn":["1011.0.17","1011.0.18"],"field":"5:7"}],"5:11":[{"s":3,"e":3,"h":"וּמְעוֹנְנִים","l":"Et harioli.","t":"Ο΄. καὶ ἀποφθεγγόμενοι. Ἀ. καὶ κληδονιζόμενοι. Σ. (καὶ) σημειοσκοπούμενοι.^19","leaf":"1011","pg":"995","fn":["1011.0.19"],"field":"5:12"}],"5:7":[{"s":19,"e":19,"h":"","l":"","t":"Cap. V. 7. ÷ ἐν τοῖς ἔθνεσιν ↙. ÷ πίπτουσα ↙.^20","leaf":"1011","pg":"995","fn":["1011.0.20"],"field":"5:7","gap":true}],"6:1":[{"s":0,"e":5,"h":"שִׁמְעוּ־נָא אֵת אֲשֶׁר־יְהוָֹה אֹמֵר","l":"Audite quaeso quod Jova dicit.","t":"Ο΄. ἀκούσατε δὴ λόγον· κύριος κύριος εἶπεν. Alia exempl. ἀκούσατε δὴ ἃ ὁ κύριος εἶπεν.^1","leaf":"1011","pg":"995","fn":["1011.1.1"],"field":"6:1"}],"6:2":[{"s":5,"e":7,"h":"וְהָאֵתָנִים מוֹסְדֵי אָרֶץ","l":"Et perennes (montes), fundamenta terrae.","t":"Ο΄. καὶ αἱ φάραγγες, θεμέλια τῆς γῆς. Ἀ. καὶ τὰ στερεά … Σ. καὶ τὰ","leaf":"1011","pg":"995","fn":[],"field":"6:2"},{"s":5,"e":7,"h":"וְהָאֵתָנִים מוֹסְדֵי אָרֶץ","l":"","t":"παλαιὰ θεμέλια τῆς γῆς. Θ. καὶ τὰ ἀρχαῖα θεμέλια τῆς γῆς.^2 Ε΄. _Ethanim fundamenta terrae._^3","leaf":"1012","pg":"996","fn":["1012.0.2","1012.0.3"],"field":"6:2","cont":true}],"6:3":[{"s":5,"e":5,"h":"הֶלְאֵתִיךָ","l":"Taedio affeci te.","t":"Ο΄. παρηνώχλησά σοι. Σ. ἐμόχθησά (s. ἐμόχθωσά) σε.^4","leaf":"1012","pg":"996","fn":["1012.0.4"],"field":"6:3"},{"s":7,"e":7,"h":"","l":"","t":"Cap. VI. 3. ÷ ἢ τί ἐλύπησά σε ↙.^26","leaf":"1013","pg":"997","fn":["1013.0.26"],"field":"6:3","gap":true}],"6:4":[{"s":4,"e":4,"h":"וּמִבֵּית","l":"","t":"Ο΄. ※ καὶ ↙ ἐξ οἴκου.^5","leaf":"1012","pg":"996","fn":["1012.0.5"],"field":"6:4"}],"6:5":[{"s":14,"e":15,"h":"מִן־הַשִּׁטִּים","l":"A Sittim.","t":"Ο΄. ἀπὸ τῶν σχοίνων. Οἱ λοιποί· Σετίμ.^6","leaf":"1012","pg":"996","fn":["1012.0.6"],"field":"6:5"},{"s":20,"e":20,"h":"צִדְקוֹת","l":"Beneficia.","t":"Ο΄. ἡ δικαιοσύνη. Σ. αἱ ἐλεημοσύναι.^7","leaf":"1012","pg":"996","fn":["1012.0.7"],"field":"6:5"}],"6:7":[{"s":5,"e":6,"h":"נַחֲלֵי־שָׁמֶן","l":"Rivorum olei.","t":"Ο΄. χιμάρων πιόνων. Ἀ. χειμάρρων ἐλαίου. Σ. ῥεῖθρα ἐλαίου.^8","leaf":"1012","pg":"996","fn":["1012.0.8"],"field":"6:7"}],"6:8":[{"s":0,"e":1,"h":"הִגִּיד לְךָ","l":"Indicavit tibi.","t":"Ο΄. εἰ ἀνηγγέλη σοι. Alia exempl. ἀνηγγέλη σοι.^9 Ἀ. Θ. ἐρρέθη σοι. Σ. εἶπέ σοι.^10","leaf":"1012","pg":"996","fn":["1012.0.9","1012.0.10"],"field":"6:8"},{"s":15,"e":18,"h":"וְהַצְנֵעַ לֶכֶת עִם־אֱלֹהֶיךָ","l":"Et humiliter ambulare cum Deo tuo.","t":"Ο΄. καὶ ἕτοιμον εἶναι τοῦ πορεύεσθαι μετὰ (alia exempl. ὀπίσω^11) κυρίου θεοῦ σου. Θ. καὶ ἀσφαλίζου τοῦ πορεύεσθαι μετὰ Ἐλωαίχ. Ε΄. καὶ φροντίζειν …^12","leaf":"1012","pg":"996","fn":["1012.0.11","1012.0.12"],"field":"6:8"}],"6:9":[{"s":3,"e":3,"h":"יִקְרָא","l":"Acclamat.","t":"Ο΄. ἐπικληθήσεται. Ἀ. καλέσει. Σ. βοήσει.^13","leaf":"1012","pg":"996","fn":["1012.0.13"],"field":"6:9"}],"6:12":[{"s":6,"e":6,"h":"שָׁקֶר","l":"Mendacia.","t":"Ο΄. ψεύδη. Alia exempl. ἄδικα.^14 Οἱ λοιποί· ψευδῆ.^15","leaf":"1012","pg":"996","fn":["1012.0.14","1012.0.15"],"field":"6:12"}],"6:13":[{"s":0,"e":6,"h":"וְגַם־אֲנִי הֶחֱלֵיתִי הַכּוֹתֶךָ הַשְׁמֵם עַל־חַטֹּאותֶךָ","l":"Et ego quoque aegrum feci percutiendo te, vastando te propter peccata tua.","t":"Ο΄. καὶ ἐγὼ ἄρξομαι τοῦ πατάξαι σε, ἀφανιῶ σε ἐν ταῖς ἁμαρτίαις σου. Alia exempl. καὶ ἐγὼ ἐβασάνισα ἐπὶ σὲ ἀφανισμῷ διὰ τὰς ἁμαρτίας σου.^16 Ἀ. καὶ ἐγὼ ἠρξάμην τοῦ πατάξαι σε ἀφανισμῷ ἐπὶ πάσαις ταῖς ἁμαρτίαις σου. Σ. καὶ ἐγὼ δὴ ἐτιμωρησάμην σε ἀφανισμῷ διὰ τὰς ἁμαρτίας σου. Θ. καὶ ἀπ’ ἀρχῆς ἐγώ εἰμι ὃς ἐκάλεσα τὴν πληγήν σου, ἐξέστησαν ἐπὶ πάσῃ ἁμαρτίᾳ σου.^17","leaf":"1012","pg":"996","fn":["1012.0.16","1012.0.17"],"field":"6:13"}],"6:14":[{"s":4,"e":8,"h":"וְיֶשְׁחֲךָ בְּקִרְבֶּךָ וְתַסֵּג וְלֹא תַפְלִיט","l":"Et inanitas tua erit in medio tui; et amovebis (tua), sed non tuta praestabis.","t":"Ο΄. καὶ συσκοτάσει ἐν σοὶ, καὶ ἐκνεύσει, καὶ οὐ μὴ διασωθῇς. Alia exempl. καὶ ἐξώσω σε ἐν σοὶ, καὶ καταλήψῃ, καὶ οὐ μὴ διασωθῇς.^18 Ἀ. καὶ καταφυ-","leaf":"1012","pg":"996","fn":["1012.0.18"],"field":"6:14"},{"s":4,"e":8,"h":"וְיֶשְׁחֲךָ בְּקִרְבֶּךָ וְתַסֵּג וְלֹא תַפְלִיט","l":"","t":"τεύσω σε ἐν ἐγκάτῳ σου, καὶ καταλήψῃ, καὶ οὐ μὴ διασώσῃς.^19 Σ. ἀλλὰ καὶ διαφθερεῖ σε εἰς τὰ ἐντός σου, καὶ ἕξεις, καὶ οὐ μὴ διασώσῃς.^20 Θ. καὶ συσκοτάσει (s. σκοτάσει) ἐν σοὶ, καὶ ἀναψύξεις, καὶ οὐ μὴ διασωθῇς.^21","leaf":"1013","pg":"997","fn":["1013.0.19","1013.0.20","1013.0.21"],"field":"6:14","cont":true}],"6:16":[{"s":0,"e":2,"h":"וְיִשְׁתַּמֵּר חֻקּוֹת עָמְרִי","l":"Nam observat sibi unusquisque statuta Omri.","t":"Ο΄. καὶ ἀφανισθήσεται νόμιμα λαοῦ μου. καὶ ἐφύλαξας τὰ δικαιώματα Ζαμβρί.^22 Σ. ὅτι ἐφυλάχθη τὰ προστάγματα Ζαμρί. Θ. καὶ ἐφύλαξας τὰ προστάγματα Ἀμρί.^23","leaf":"1013","pg":"997","fn":["1013.0.22","1013.0.23"],"field":"6:16"},{"s":3,"e":4,"h":"וְכֹל מַעֲשֵׂה","l":"","t":"Ο΄. καὶ πάντα τὰ ἔργα (Ἀ. ποιήματα^24).","leaf":"1013","pg":"997","fn":["1013.0.24"],"field":"6:16"},{"s":8,"e":8,"h":"בְּמֹעֲצוֹתָם","l":"In consiliis eorum.","t":"Ο΄. ἐν ταῖς ὁδοῖς (alia exempl. βουλαῖς^25) αὐτῶν.","leaf":"1013","pg":"997","fn":["1013.0.25"],"field":"6:16"}],"7:1":[{"s":0,"e":1,"h":"אַלְלַי לִי","l":"Vae mihi!","t":"Ο΄. οἴμοι. Ἀ. Σ. ἀλαλαί . .^1","leaf":"1013","pg":"997","fn":["1013.1.1"],"field":"7:1"},{"s":4,"e":5,"h":"כְּאָסְפֵּי־קַיִץ","l":"Sicut collectiones fructuum aestivorum.","t":"Ο΄. ὡς συνάγων καλάμην ἐν ἀμητῷ. Σ. ὡς ἐν τοῖς ἐσχάτοις τῆς ὀπώρας.^2","leaf":"1013","pg":"997","fn":["1013.1.2"],"field":"7:1"},{"s":12,"e":13,"h":"אִוְּתָה נַפְשִׁי","l":"Desiderat anima mea.","t":"Ο΄. οἴμοι ψυχή ※ Οἱ Γ΄. μου ↙.^3 Ἄλλος· ἐπεπόθησεν ἡ ψυχή μου.^4","leaf":"1013","pg":"997","fn":["1013.1.3","1013.1.4"],"field":"7:1"}],"7:2":[{"s":0,"e":0,"h":"אָבַד","l":"","t":"Ο΄. ÷ ὅτι ↙ ἀπόλωλεν. Οἱ λοιποί· ἐκλέλοιπεν.^5","leaf":"1013","pg":"997","fn":["1013.1.5"],"field":"7:2"},{"s":1,"e":1,"h":"חָסִיד","l":"Pius.","t":"Ο΄. εὐσεβὴς (potior scriptura εὐλαβής^6). Ἀ. Σ. ὅσιος.^7","leaf":"1013","pg":"997","fn":["1013.1.6","1013.1.7"],"field":"7:2"},{"s":9,"e":9,"h":"יֶאֱרֹבוּ","l":"Insidiantur.","t":"Ο΄. δικάζονται. Οἱ Γ΄. ἐνεδρεύουσιν.^8","leaf":"1013","pg":"997","fn":["1013.1.8"],"field":"7:2"},{"s":13,"e":14,"h":"יָצוּדוּ חֵרֶם","l":"Venantur ad internecionem (s. reti).","t":"Ο΄. ἐκθλίβουσιν ἐκθλιβῇ. Ἀ. Σ. θηρεύουσιν ἀναθέματι.^9","leaf":"1013","pg":"997","fn":["1013.1.9"],"field":"7:2"}],"7:3":[{"s":7,"e":13,"h":"בַּשִּׁלּוּם וְהַגָּדוֹל דֹּבֵר הַוַּת נַפְשׁוֹ הוּא וַיְעַבְּתוּהָ","l":"Pro remuneratione; et magnus, eloquitur libidinem animi sui ille, et (tres simul) contexunt eam (rem).","t":"Ο΄. εἰρηνικοὺς λόγους ἐλάλησε, καταθύμιον ψυχῆς αὐτοῦ ἐστιν, καὶ ἐξελοῦμαι (τὰ ἀγαθὰ αὐτῶν). Σ. ἐν ἀνταποδόσει, καὶ ὁ μέγας λαλεῖ τὴν ἐπιθυμίαν τῆς ψυχῆς αὐτοῦ, καὶ κατὰ τοὺς δασεῖς ἡ δασύτης αὐτοῦ.^10","leaf":"1013","pg":"997","fn":["1013.1.10"],"field":"7:3"}],"7:4":[{"s":0,"e":10,"h":"טוֹבָם כְּחֵדֶק יָשָׁר מִמְּסוּכָה יוֹם מְצַפֶּיךָ פְּקֻדָּתְךָ בָאָה עַתָּה תִהְיֶה מְבוּכָתָם","l":"Optimus eorum est instar spinae, probissimus prae sepe spinosa; dies speculatorum tuorum (a prophetis tuis praedicta), visitatio tua venit; nunc erit perplexitas eorum.","t":"Ο΄. τὰ ἀγαθὰ αὐτῶν, ὡς","leaf":"1013","pg":"997","fn":[],"field":"7:4"},{"s":0,"e":10,"h":"טוֹבָם כְּחֵדֶק יָשָׁר מִמְּסוּכָה יוֹם מְצַפֶּיךָ פְּקֻדָּתְךָ בָאָה עַתָּה תִהְיֶה מְבוּכָתָם","l":"","t":"σῆς (Ἀ. ὡς βολίς. Σ. Θ. ὡς ἄκανθα^11) ἐκτρώγων, καὶ βαδίζων ἐπὶ κανόνος ἐν ἡμέρᾳ σκοπιᾶς (σου)· οὐαὶ (alia exempl. ÷ οὐαὶ οὐαὶ ↙^12) αἱ ἐκδικήσεις σου ἥκασι· νῦν ἔσονται κλαυθμοὶ αὐτῶν. Σ. ὁ ἀγαθὸς αὐτῶν ὡς ἄκανθα, ὁ ὀρθὸς ὡς ἐξ ἐμφραγμοῦ ἐν ἡμέρᾳ τῶν προσκοπευόντων σοι· ἡ ἐπισκοπή σου ἦλθε· νῦν ἔσται κλαυθμὸς αὐτῶν.^13","leaf":"1014","pg":"998","fn":["1014.0.11","1014.0.12","1014.0.13"],"field":"7:4","cont":true}],"7:6":[{"s":5,"e":5,"h":"קָמָה","l":"","t":"Ο΄. ἐπαναστήσεται. Aliter: Ο΄. ἀναστήσεται.^14","leaf":"1014","pg":"998","fn":["1014.0.14"],"field":"7:6"}],"7:7":[{"s":1,"e":2,"h":"בַּיהֹוָה אֲצַפֶּה","l":"_In Jovam intuebor._","t":"Ο΄. ἐπὶ τὸν κύριον ἐπιβλέψομαι. Alia exempl. ἐν τῷ κυρίῳ ἀποσκοπεύσω.^15 Θ. πρὸς τὸν κύριον ἐπιβλέψομαι.^16","leaf":"1014","pg":"998","fn":["1014.0.15","1014.0.16"],"field":"7:7"}],"7:8":[{"s":7,"e":12,"h":"כִּי־אֵשֵׁב בַּחֹשֶׁךְ יְהֹוָה אוֹר לִי","l":"_Quamvis sedeam in tenebris, Jova lux_ est _mihi._","t":"Ο΄. διότι ἐὰν καθίσω (alia exempl. πορευθῶ^17) ἐν τῷ σκότει, κύριος φωτιεῖ μοι (alia exempl. φῶς μοι^18). ※ Θ. φωτιεῖ μοι ↙.^19","leaf":"1014","pg":"998","fn":["1014.0.17","1014.0.18","1014.0.19"],"field":"7:8"}],"7:11":[{"s":0,"e":6,"h":"יוֹם לִבְנוֹת גְּדֵרָ֑יִךְ יוֹם הַהוּא יִרְחַק־חֹק׃ יוֹם הוּא","l":"_Dies ad aedificandum macerias tuas_ (instat); _die illo longe fiet decretum. Die illo._","t":"Ο΄. ἡμέρα ἀλοιφῆς πλίνθου, ἐξάλειψίς σου ἡ ἡμέρα ἐκείνη, καὶ ἀποτρίψεται (alia exempl. ἀπώσεται^20) νόμιμά [σου] (Σ. ἐπιταγή. Θ. πρόσταγμα^21) ἡ ἡμέρα ἐκείνη. Σ. ἡμέρα τοῦ οἰκοδομῆσαι τοὺς φραγμούς σου· ἐν τῇ ἡμέρᾳ ἐκείνῃ μακρὰν ἔσται ἡ ἐπιταγή· ἡ δὲ ἡμέρα ἐκείνη.^22","leaf":"1014","pg":"998","fn":["1014.0.20","1014.0.21","1014.0.22"],"field":"7:11"},{"s":5,"e":6,"h":"יִרְחַק־חֹק׃ יוֹם הוּא וְעָדֶיךָ יָבוֹא לְמִנִּי אַשּׁוּר וְעָרֵי מָצוֹר וּלְמִנִּי מָצוֹר וְעַד־נָהָר וְיָם מִיָּם וְהַר הָהָר","l":"_Longe fiet decretum. Die illo ad te venient ex Assyria, et urbibus Aegypti, et inde ab Aegypto usque ad fluvium, et_ ad _mare a mari, et a monte usque ad montem._","t":"Ο΄. καὶ ἀποτρίψεται νόμιμά σου ἡ ἡμέρα ἐκείνη. καὶ αἱ πόλεις σου ἥξουσιν εἰς ὁμαλισμὸν (alia exempl. ÷ εἰς συγκλεισμὸν^23), καὶ ↙ εἰς διαμερισμὸν ※ Οἱ Γ΄. Ἀσσυρίων ↙.^24 καὶ αἱ πόλεις σου αἱ ὀχυραὶ εἰς διαμερισμὸν ἀπὸ Τύρου (Πάντες· περιοχὴν, s. περίφραγμα, s. πολιορκίαν^25) ἕως τοῦ ποταμοῦ, καὶ ἀπὸ θαλάσσης ἕως θαλάσσης, καὶ ἀπὸ ὄρους ἕως τοῦ ὄρους. Ἀ. μακρυνθήσεται ἡ ἀκρισία τῆς ἡμέρας ἐκείνης, καὶ ἕως οὗ ἥξει ἐξ Ἀσσοὺρ καὶ πόλεως πολιορκίας, καὶ ἀπὸ πολιορκίας καὶ ἕως ποταμοῦ καὶ θαλάσσης, καὶ ἀπὸ θαλάσσης καὶ ὄρους τοῦ ὄρους.^26 Θ. μακρυνεῖ πρόσταγμα ἡ ἡμέρα ἐκείνη, καὶ αἱ πόλεις σου ἥξουσιν ἐξ Ἀσσοὺρ καὶ πόλεως","leaf":"1014","pg":"998","fn":["1014.0.23","1014.0.24","1014.0.25","1014.0.26"],"field":"7:11"},{"s":5,"e":6,"h":"יִרְחַק־חֹק׃ יוֹם הוּא וְעָדֶיךָ יָבוֹא לְמִנִּי אַשּׁוּר וְעָרֵי מָצוֹר וּלְמִנִּי מָצוֹר וְעַד־נָהָר וְיָם מִיָּם וְהַר הָהָר","l":"","t":"περιοχῆς, καὶ ἀπὸ περιοχῆς ἕως τοῦ ὕδατος τοῦ ποταμοῦ καὶ τῆς θαλάσσης, καὶ ἀπὸ τοῦ ὄρους ἕως τοῦ ὄρους.^27","leaf":"1015","pg":"999","fn":["1015.0.27"],"field":"7:11","cont":true}],"7:12":[{"s":12,"e":15,"h":"וְיָם מִיָּם וְהַר הָהָר","l":"","t":"Ἄλλος· ἡμέρα ὕδατος καὶ θορύβου.^28","leaf":"1015","pg":"999","fn":["1015.0.28"],"field":"7:12"}],"7:14":[{"s":13,"e":13,"h":"כִּימֵי","l":"","t":"Ο΄. καθὼς αἱ ἡμέραι. Alia exempl. κατὰ τὰς ἡμέρας.^29 Σ. καθ᾽ ὅσον αἱ ἡμέραι.^30","leaf":"1015","pg":"999","fn":["1015.0.29","1015.0.30"],"field":"7:14"}],"7:15":[{"s":4,"e":4,"h":"אַרְאֶנּוּ","l":"_Ostendam ei._","t":"Ο΄. ὄψεσθε. Alia exempl. δείξω αὐτοῖς.^31 Σ. . αὐτῷ.^32","leaf":"1015","pg":"999","fn":["1015.0.31","1015.0.32"],"field":"7:15"}],"7:17":[{"s":3,"e":4,"h":"כְּזֹחֲלֵי אֶרֶץ","l":"_Sicut reptilia terrae._","t":"Ο΄. σύροντες γῆν. Σ. συρόμενος ἐπὶ τῆς γῆς.^33","leaf":"1015","pg":"999","fn":["1015.0.33"],"field":"7:17"}],"7:18":[{"s":8,"e":8,"h":"לִשְׁאֵרִית","l":"_Residuo._","t":"Ο΄. τοῖς καταλοίποις. Σ. τῷ καταλείμματι.^34","leaf":"1015","pg":"999","fn":["1015.0.34"],"field":"7:18"},{"s":10,"e":11,"h":"לֹא־הֶחֱזִיק","l":"_Non retinet._","t":"Ο΄. καὶ οὐ συνέσχεν (alia exempl. οὐκ ἐκράτησεν^35). Σ. οὐκ ἐκαρτέρησεν.^36","leaf":"1015","pg":"999","fn":["1015.0.35","1015.0.36"],"field":"7:18"},{"s":12,"e":12,"h":"לָעַד","l":"_In perpetuum._","t":"Ο΄. Ε΄. εἰς μαρτύριον. Σ. εἰς ἀεί. Θ. εἰς τέλος.^37","leaf":"1015","pg":"999","fn":["1015.0.37"],"field":"7:18"}],"7:19":[{"s":4,"e":4,"h":"וְתַשְׁלִיךְ","l":"_Et projicies._","t":"Ο΄. καὶ ἀπορριφήσονται (alia exempl. ἀπορρίψει^38).","leaf":"1015","pg":"999","fn":["1015.0.38"],"field":"7:19"}],"7:20":[{"s":0,"e":0,"h":"תִּתֵּן","l":"_Praestabis._","t":"Ο΄. δώσει. Ἀ. Σ. Θ. δώσεις.^39","leaf":"1015","pg":"999","fn":["1015.0.39"],"field":"7:20"},{"s":8,"e":9,"h":"מִימֵי קֶדֶם","l":"_Inde a diebus antiquitatis._","t":"Ο΄. κατὰ τὰς ἡμέρας τὰς ἔμπροσθεν. Aliter: Ο΄. κατὰ τὰς ἡμέρας τὰς ἀπ᾽ ἀρχῆς. Ἀ. ὁμοίως τοῖς Ο΄. ἀρχῆθεν. Σ. ἐξ ἡμερῶν ἀρχαίων. Θ. . . τὰς ἔμπροσθεν.^40","leaf":"1015","pg":"999","fn":["1015.0.40"],"field":"7:20"}]},"notes":{"1004.1.1":{"la":"Sic Ald., Codd. 87, 91, alii, Hieron., Syro-hex.","en":"Thus Ald., Codd. 87, 91, and others, Hieron., Syro-hex."},"1004.1.2":{"la":"Syro-hex. ܐ. ܦܬܓܡܐ ܕܡܪܝܐ܀ ܣ. ܬ. ܐܝܟ ܗܠܝܢ[?] ܫܒܥܝܢ܀","en":"Syro-hex. ܐ. ܦܬܓܡܐ ܕܡܪܝܐ܀ ܣ. ܬ. ܐܝܟ ܗܠܝܢ[?] ܫܒܥܝܢ܀"},"1004.1.3":{"la":"Sic Comp. (cum Μωρασθ.), Codd. 22 (sine τὸν), 23, 51, 62 (cum Μωραθήτην), 86 (in marg. cum ἀμωραθίτην), alii. Cf. Hex. ad Jerem. xxvi. 18. S. Cyril. in XII Proph. p. 392 B: Χρὴ εἰδέναι πάλιν, ὡς Ἑβραῖοι γεγράφασιν ἀντὶ τοῦ Μωραθὶ τὸν Μωραθίτην, ἵνα μὴ ὡς ἐκ πατρὸς, ἀλλ’ ὡς ἐκ τόπου σημαίνηται … συμφέρονται δὲ τῇ ἐκδόσει καὶ οἱ ἕτεροι τῶν ἑρμηνευτῶν.","en":"Thus Comp. (with Μωρασθ.), Codd. 22 (without τὸν), 23, 51, 62 (with Μωραθήτην), 86 (in the margin with ἀμωραθίτην), and others. Cf. Hex. on Jerem. xxvi. 18. S. Cyril. in XII Proph. p. 392 B: Χρὴ εἰδέναι πάλιν, ὡς Ἑβραῖοι γεγράφασιν ἀντὶ τοῦ Μωραθὶ τὸν Μωραθίτην, ἵνα μὴ ὡς ἐκ πατρὸς, ἀλλ’ ὡς ἐκ τόπου σημαίνηται … συμφέρονται δὲ τῇ ἐκδόσει καὶ οἱ ἕτεροι τῶν ἑρμηνευτῶν."},"1004.1.4":{"la":"Syro-hex. in marg. sine nom. ܠܣܗܕܐ[?]܀","en":"Syro-hex. in the margin without a name ܠܣܗܕܐ[?]܀"},"1004.1.5":{"la":"Hieron.: “Et sit eis Dominus _in testimonium_, sive ut in Hebraico legitur, _in testem;_ vel ut apertius interpretatus est Sym., _testificans._” Cf. Hex. ad Psal. lxxxviii. 38.","en":"Hieron.: “And let the Lord be to them _for a testimony_, or as is read in the Hebrew, _for a witness;_ or as Sym. rendered more plainly, _testifying._” Cf. Hex. on Psal. lxxxviii. 38."},"1004.1.6":{"la":"Syro-hex. ܐ. ܘܢܬܬܡܣܘܢ[?]܀ ܬ. ܘܢܬܦܫܪܘܢ[?]܀","en":"Syro-hex. ܐ. ܘܢܬܬܡܣܘܢ[?]܀ ܬ. ܘܢܬܦܫܪܘܢ[?]܀"},"1004.1.7":{"la":"Idem: ܣ. ܐܝܠܝܢ[?] ܐܢܘܢ ܪ̈ܡܬܐ܀","en":"The same: ܣ. ܐܝܠܝܢ[?] ܐܢܘܢ ܪ̈ܡܬܐ܀"},"1004.1.8":{"la":"Idem: ܐ. ܠܟܪ̈ܘܡܐ[?]܀ ܣ. ܬ. ܠܓܒ̈ܠܐ[?]܀ Ad Aquilam cf. Hex. ad Psal. lxxviii. 1. Jerem. xxvi. 18. Mich. iii. 12.","en":"The same: ܐ. ܠܟܪ̈ܘܡܐ[?]܀ ܣ. ܬ. ܠܓܒ̈ܠܐ[?]܀ On Aquila cf. Hex. on Psal. lxxviii. 1. Jerem. xxvi. 18. Mich. iii. 12."},"1004.1.9":{"la":"Cod. 86. Cf. Hex. ad Jerem. ix. 11.","en":"Cod. 86. Cf. Hex. on Jerem. ix. 11."},"1004.1.10":{"la":"Idem. Cf. Hex. ad Job. xxx. 29. Jesai. xiii. 21.","en":"The same. Cf. Hex. on Job. xxx. 29. Jesai. xiii. 21."},"1004.1.11":{"la":"Syro-hex. ܣ. ܬ. ܡܬܩܛܪܢܝܬܐ[?] ܗܝ܀ Cf. Hex. ad Jerem. xxx. 12, 15.","en":"Syro-hex. ܣ. ܬ. ܡܬܩܛܪܢܝܬܐ[?] ܗܝ܀ Cf. Hex. on Jerem. xxx. 12, 15."},"1004.1.12":{"la":"Cod. 86 (cum scriptura ἀναγγείληται).","en":"Cod. 86 (with the reading ἀναγγείληται)."},"1004.1.13":{"la":"Sic Cod. XII (in marg.), Syro-hex.","en":"Thus Cod. XII (in the margin), Syro-hex."},"1004.1.14":{"la":"Syro-hex. ܐ. ܣ. ܒܟܠܬܐ[?] ܠܐ ܬܒܟܘܢ܀ ܬ. ܒܟܝܐ[?]܀ Euseb. in Onomastico s. v. Ἐναχείμ: Ἐναχεὶμ, ἢ ἐν Βαχείν. Μιχαίας. Ἀκύλας, Σύμμαχος· ἐν κλαυθμῷ. Hieron.: “BACHIM in nostra lingua _planctum_ et _fletum_ sonat. Denique, exceptis LXX, omnes κλαυθμὸν, id est, _fletum_, transtulerunt.”","en":"Syro-hex. ܐ. ܣ. ܒܟܠܬܐ[?] ܠܐ ܬܒܟܘܢ܀ ܬ. ܒܟܝܐ[?]܀ Euseb. in the Onomasticon s. v. Ἐναχείμ: Ἐναχεὶμ, ἢ ἐν Βαχείν. Μιχαίας. Ἀκύλας, Σύμμαχος· ἐν κλαυθμῷ. Hieron.: “BACHIM in our language means _lamentation_ and _weeping_. Finally, except the LXX, all translated κλαυθμὸν, that is, _weeping_.”"},"1004.1.15":{"la":"Sic Comp., Codd. 36, 40, alii, Hieron. (qui _derisum_ vertit), Syro-hex. (ܠܓܘܚܟܐ[?]).","en":"Thus Comp., Codd. 36, 40, and others, Hieron. (who renders _derision_), Syro-hex. (ܠܓܘܚܟܐ[?])."},"1004.1.16":{"la":"Syro-hex. ܐ. ܒܒܝܬܐ ܕܥܦܪܐ ܕܝܠܝ[?]܀ ܣ. ܡܢܩܝܬܐ[?]܀ ܬ. ܕܥܦܪܐ[?]܀ Syriacum ܡܢܩܝܬܐ[?] ponitur pro σπονδεῖον in Hex. ad Jerem. lii. 19, not. 50; necnon pro κοτύλη Ezech. xlv. 14; quae cum Hebraeis nostris quid commune habeant nemo facile dixerit.","en":"Syro-hex. ܐ. ܒܒܝܬܐ ܕܥܦܪܐ ܕܝܠܝ[?]܀ ܣ. ܡܢܩܝܬܐ[?]܀ ܬ. ܕܥܦܪܐ[?]܀ The Syriac ܡܢܩܝܬܐ[?] is used for σπονδεῖον in Hex. on Jerem. lii. 19, note 50; also for κοτύλη"},"1005.0.17":{"la":"Syro-hex. ܐ. ܥܒܪܘ ܠܟܘܢ ܥܡܘܪܬܐ[?] ܕܫܦܝܪ܀ ܣ. ܥܒܪܝܢ ܠܟܘܢ ܝܬ̈ܒܬܐ[?] ܫܦܝܪ܀ ܬ. ܕܒܗܬܬܐ[?] ܒܗܬܬܐ ܡܬܒܗܬܢܝܬܐ[?] ܗܝ ܡܕܝܢܬܐ ܗܕܐ ܒܗܬܬܐ܀ Graeca valde incerta sunt, praesertim Theodotionis, quae sensum fere nullum, nedum cum Hebraeis congruentem, fundere videntur.","en":"Syro-hex. ܐ. ܥܒܪܘ ܠܟܘܢ ܥܡܘܪܬܐ[?] ܕܫܦܝܪ܀ ܣ. ܥܒܪܝܢ ܠܟܘܢ ܝܬ̈ܒܬܐ[?] ܫܦܝܪ܀ ܬ. ܕܒܗܬܬܐ[?] ܒܗܬܬܐ ܡܬܒܗܬܢܝܬܐ[?] ܗܝ ܡܕܝܢܬܐ ܗܕܐ ܒܗܬܬܐ܀ The Greek is very uncertain, especially that of Theodotion, which seems to yield almost no sense, much less one agreeing with the Hebrew."},"1005.0.18":{"la":"Sic Codd. 62, 147, Hieron., et (cum scriptura Σαιννὰν) Ald., Codd. 42, 68, alii.","en":"Thus Codd. 62, 147, Hieron., and (with the reading Σαιννὰν) Ald., Codd. 42, 68, and others."},"1005.0.19":{"la":"Syro-hex. ܐ. ܕܝܬܒܐ[?]܀ Deinde Cod. 86 affert: Ἀ. Σαναὼν ἡ εὐθύνουσα (sic); S. Cyril. autem in XII Proph. p. 401 D: Ἐκδεδώκασι μὲν οἱ Ο΄ Σενναὰρ, Ἀκύλας δὲ ἔφη Σενὰν, εὐσθενοῦσαν δὲ ὁ Σύμμαχος, τάχα που τουτὶ τοῦ Σενὰν ὑπεμφαίνοντος. Denique Euseb. in Onomastico s. v.: Σενναὰρ, ἐν Μιχαίᾳ. Ἀκύλας· Σενναάρ [Hieron. _Sennam_]. Σύμμαχος· εὐθηνοῦσαν.","en":"Syro-hex. ܐ. ܕܝܬܒܐ[?]܀ Next, Cod. 86 cites: Ἀ. Σαναὼν ἡ εὐθύνουσα (sic); S. Cyril., however, in XII Proph. p. 401 D: Ἐκδεδώκασι μὲν οἱ Ο΄ Σενναὰρ, Ἀκύλας δὲ ἔφη Σενὰν, εὐσθενοῦσαν δὲ ὁ Σύμμαχος, τάχα που τουτὶ τοῦ Σενὰν ὑπεμφαίνοντος. Finally Euseb. in the Onomasticon s. v.: Σενναὰρ, ἐν Μιχαίᾳ. Ἀκύλας· Σενναάρ [Hieron. _Sennam_]. Σύμμαχος· εὐθηνοῦσαν."},"1005.0.20":{"la":"Hieron.: “Porro quod sequitur: _Non est egressa quae habitat in Sennam_, quae interpretatur _exitus_, sive ut Sym. vertit: _Non est egressa habitatio abundans_, de eadem Samaria dicitur.” Paulo aliter Syro-hex.: Σ. ἡ κατοικία εὐθηνοῦσα (ܗܝ ܕܡܬܒܣܡܐ[?] ܡܥܡܪܬܐ). (In loco S. Cyrilli pro εὐσθενοῦσαν etiam invitis libris reponendum esse εὐθηνοῦσαν ex ipsa S. Patris enarratione patet, in qua olim edebatur: εὐσθενῆ τε ὅτι πίων ἡ χώρα, καὶ λῃΐοις κατάκομος, πῶς ἔστιν ἀμφιβαλεῖν. Pro εὐσθενῆ τε in uno libro soloece scriptum εὐσθενεῖται δέ; in altero autem εὐθυνεῖται δὲ, leviter corruptum ex εὐθηνεῖται δὲ, in quo verbo utraque forma, activa et media, usu sancita est. Adde quod _regionis fertilitas_ et _frugum abundantia_ ad εὐθηνίαν, non ad εὐσθένειαν pertinent.)","en":"Hieron.: “Further, what follows: _She that dwells in Sennam has not gone forth_, which is interpreted _going out_, or as Sym. rendered: _The abundant habitation has not gone forth_, is said of the same Samaria.” Somewhat differently Syro-hex.: Σ. ἡ κατοικία εὐθηνοῦσα (ܗܝ ܕܡܬܒܣܡܐ[?] ܡܥܡܪܬܐ). (In the passage of S. Cyril, εὐθηνοῦσαν must be restored for εὐσθενοῦσαν even against the books, as is clear from the holy Father's own explanation, in which it was formerly printed: εὐσθενῆ τε ὅτι πίων ἡ χώρα, καὶ λῃΐοις κατάκομος, πῶς ἔστιν ἀμφιβαλεῖν. For εὐσθενῆ τε one book has the solecism εὐσθενεῖται δέ; another, however, εὐθυνεῖται δὲ, slightly corrupted from εὐθηνεῖται δὲ, a verb in which both forms, active and middle, are sanctioned by usage. Add that _the fertility of the region_ and _abundance of crops_ belong to εὐθηνίαν, not to εὐσθένειαν.)"},"1005.0.21":{"la":"Syro-hex. ܬ. (ܗܝ) ܕܝܬܒܐ ܒܨܥܢ܀ Pro ܨܥܢ, quae utriusque versionis Syriacae scriptura textualis est, Middeld. Graece interpretatus est Τάνιν (cf. Psal. lxxvii. 43. Jesai. xix. 11, 13. xxx. 4), reclamante Cod. 86, qui affert: Θ. Σανιὼν εἰς κοπετόν.","en":"Syro-hex. ܬ. (ܗܝ) ܕܝܬܒܐ ܒܨܥܢ܀ For ܨܥܢ, which is the textual reading of both Syriac versions, Middeld. gave the Greek Τάνιν (cf. Psal. lxxvii. 43. Jesai. xix. 11, 13. xxx. 4), against Cod. 86, which cites: Θ. Σανιὼν εἰς κοπετόν."},"1005.0.22":{"la":"Cod. 86. (In textu pro κόψασθε stant Codd. II, III, 106, 311, Hieron., Syro-hex.)","en":"Cod. 86. (In the text Codd. II, III, 106, 311, Hieron., Syro-hex. stand for κόψασθε.)"},"1005.0.23":{"la":"Syro-hex. ܣ. ܠܒܪ[?] ܠܒܪ[?]܀","en":"Syro-hex. ܣ. ܠܒܪ[?] ܠܒܪ[?]܀"},"1005.0.24":{"la":"Idem: ܐ. ܡܛܠ ܕܐܬܟܪܗܬ[?] ܒ ܠܛܒܬܐ ܝܬܒܬܐ ܕܡܪܘܬ܀","en":"The same: ܐ. ܡܛܠ ܕܐܬܟܪܗܬ[?] ܒ ܠܛܒܬܐ ܝܬܒܬܐ ܕܡܪܘܬ܀"},"1005.0.25":{"la":"Idem: ܣ. ܡܛܠ ܕܣܒܪܬ (ܕܣܟܝܬ ?) ܠܛܒܬܐ ܗܝ ܕܝܬܒܐ ܗܝ ܕܡܡܪܡܪܐ܀ Paulo aliter Hieron.: “_Quia infirmata est in bono quae habitat in Maroth_, id est, _in amaritudinibus_, sive ut Sym. vertit, _habitatio ad amaritudinem provocans_, hoc est, ἡ κατοικία ἡ παραπικραίνουσα.”","en":"The same: ܣ. ܡܛܠ ܕܣܒܪܬ (ܕܣܟܝܬ ?) ܠܛܒܬܐ ܗܝ ܕܝܬܒܐ ܗܝ ܕܡܡܪܡܪܐ܀ Somewhat differently Hieron.: “_For she that dwells in Maroth has become weak for good_, that is, _in bitternesses_, or as Sym. rendered, _the habitation provoking to bitterness_, that is, ἡ κατοικία ἡ παραπικραίνουσα.”"},"1005.0.26":{"la":"Syro-hex. ܬ. ܕܡܣܟܝܐ ܠܛܒܬܐ ܕܝܬܒܐ ܒܪܘܡܐ܀","en":"Syro-hex. ܬ. ܕܡܣܟܝܐ ܠܛܒܬܐ ܕܝܬܒܐ ܒܪܘܡܐ܀"},"1005.0.27":{"la":"Sic Syro-hex. in textu. Pronomen abest a Comp., Ald., Codd. 68, 87*, aliis, Hieron.","en":"Thus Syro-hex. in the text. The pronoun is absent from Comp., Ald., Codd. 68, 87*, and others, Hieron."},"1005.0.28":{"la":"Sic Codd. III, 22, 23, 26, alii, Syro-hex.","en":"Thus Codd. III, 22, 23, 26, and others, Syro-hex."},"1005.0.29":{"la":"Syro-hex. ܐ. ܣ. ܬ. ܡܛܠ ܕܩܘܪ̈ܒܢܐ܀ “Ἀ. Σ. Θ. _propter munera_ [quasi Syrus dedisset ܡܛܠ ܩܘܪ̈ܒܢܐ]. Vix credibile, interpretes ita revera vertisse לָכֵן תִּתְּנִי. Reddiderant haec fortasse διὰ τοῦτο δώσεις, quae vero in cod. Graeco Syri in διὰ τὰς δόσεις depravata erant.”—_Middeld._ Lectio ob nimiam brevitatem difficilis, quaeque adhuc explicatorem exspectat. Quod si διὰ τὰς δόσεις in Graeco invenisset Noster, proculdubio vertisset ܡܛܠ ܡܘܗ̈ܒܬܐ.","en":"Syro-hex. ܐ. ܣ. ܬ. ܡܛܠ ܕܩܘܪ̈ܒܢܐ܀ “Ἀ. Σ. Θ. _on account of the gifts_ [as if the Syrian had given ܡܛܠ ܩܘܪ̈ܒܢܐ]. It is hardly credible that the translators really rendered לָכֵן תִּתְּנִי thus. Perhaps they had rendered it διὰ τοῦτο δώσεις, which, however, in the Syrian's Greek codex had been corrupted into διὰ τὰς δόσεις.”—_Middeld._ The reading is difficult because of its excessive brevity, and still awaits an explainer. But if our translator had found διὰ τὰς δόσεις in the Greek, he would without doubt have rendered ܡܛܠ ܡܘܗ̈ܒܬܐ."},"1005.0.30":{"la":"Syro-hex. ܐ. ܕܕܓܠܘܬܐ܀ ܣ. ܐܟܙܝܒ܀ ܬ. ܡܢ ܐܘܠܨܢܐ܀ 6 L 2","en":"Syro-hex. ܐ. ܕܕܓܠܘܬܐ܀ ܣ. ܐܟܙܝܒ܀ ܬ. ܡܢ ܐܘܠܨܢܐ܀"},"1006.0.31":{"la":"Theodoret.: κατὰ δὲ τὸν Ἀκύλαν ἑνικῶς τεθεικότα τὸν κληρόνομον, καὶ βαθυτέραν εὑρίσκομεν διάνοιαν· ἐν ἐρημίᾳ γὰρ, φησὶν, ἔσῃ τοὺς ματαίους οἴκους οἰκοῦσα, ἕως τὸν κληρόνομον [Matth. xxi. 38] ἀγάγω σοι.","en":"Theodoret.: κατὰ δὲ τὸν Ἀκύλαν ἑνικῶς τεθεικότα τὸν κληρόνομον, καὶ βαθυτέραν εὑρίσκομεν διάνοιαν· ἐν ἐρημίᾳ γὰρ, φησὶν, ἔσῃ τοὺς ματαίους οἴκους οἰκοῦσα, ἕως τὸν κληρόνομον [Matth. xxi. 38] ἀγάγω σοι."},"1006.0.32":{"la":"Syro-hex. ܐ. ܐܝܟ ܫܒܥܝܢ܀ ܣ. ܐܝܬܐ ܐܦ ܠܟܝ܀ ܬ. ܐܝܬܐ ܠܟܝ܀ In textu ἀγάγω σοι pro ἀγάγωσι habent Ald., Codd. III, 22, 36, 51, alii, Hieron., invito Syro-hex.","en":"Syro-hex. ܐ. ܐܝܟ ܫܒܥܝܢ܀ ܣ. ܐܝܬܐ ܐܦ ܠܟܝ܀ ܬ. ܐܝܬܐ ܠܟܝ܀ In the text Ald., Codd. III, 22, 36, 51, and others, Hieron. have ἀγάγω σοι for ἀγάγωσι, against Syro-hex."},"1006.0.33":{"la":"Obelus est in Syro-hex. Hieron. (qui jungit: ἡ δόξα τ. θ. Ἰσραὴλ, ξύρησαι κ. τ. ἑ.): “Hoc quod dictum est a LXX, _Gloria filiae Israel_, addentibus _filiae_, Hebraei in fine superioris capituli legunt.”","en":"The obelus is in Syro-hex. Hieron. (who joins: ἡ δόξα τ. θ. Ἰσραὴλ, ξύρησαι κ. τ. ἑ.): “This which was said by the LXX, _The glory of the daughter of Israel_, adding _of the daughter_, the Hebrews read at the end of the preceding chapter.”"},"1006.0.34":{"la":"Hieron.: “Denique et Sym. ita transtulit: ἔτι κληρόνομον—Ἰσραὴλ, hoc est: _Adhuc heredem adducam et tibi, habitatio Maresa; usque Odollam veniet gloriae Israel_, hoc est, quae gloriosa es in urbibus Israel.”","en":"Hieron.: “Finally Sym. too translated thus: ἔτι κληρόνομον—Ἰσραὴλ, that is: _Yet will I bring an heir to thee also, O habitation of Maresa; as far as Odollam shall come the glory of Israel_, that is, thou who art glorious among the cities of Israel.”"},"1006.0.35":{"la":"Sic Ald., Codd. 22, 36, 51, alii. Cod. 86: λ. Σιών; ubi λοιποὶ de _aliis exemplaribus_ intelligendum. Cf. Hex. ad Ezech. iii. 26.","en":"Thus Ald., Codd. 22, 36, 51, and others. Cod. 86: λ. Σιών; where λοιποὶ is to be understood of _other copies_. Cf. Hex. on Ezech. iii. 26."},"1006.0.36":{"la":"Sic Comp., Ald., Codd. XII (in marg.), 22, 36, 42, alii, Hieron., Syro-hex. (ܠܓܙܙܐ[?]).","en":"Thus Comp., Ald., Codd. XII (in the margin), 22, 36, 42, and others, Hieron., Syro-hex. (ܠܓܙܙܐ[?])."},"1006.0.37":{"la":"Syro-hex. ܐ. ܩܪܚܘܬܐ܀ ܬ. ܠܓܪܙܘܬܐ[?]܀ Cod. 86 affert: Ἑβρ. τὴν χηρείαν. Ἀ. Σ. φαλάκρωσιν.","en":"Syro-hex. ܐ. ܩܪܚܘܬܐ܀ ܬ. ܠܓܪܙܘܬܐ[?]܀ Cod. 86 cites: Ἑβρ. τὴν χηρείαν. Ἀ. Σ. φαλάκρωσιν."},"1006.1.1":{"la":"Cod. 86, teste Waltono. Lectionem non agnoscunt Stephanopolus et Cozza.","en":"Cod. 86, on the testimony of Walton. Stephanopolus and Cozza do not recognize the reading."},"1006.1.2":{"la":"Cod. 86. Aquilae lectio manca esse videtur, sic fortasse supplenda: ὅτι ἔστιν ἐπὶ ἰσχυρὸν χ. αὐτοῦ (s. αὐτῶν), non aliter ac Hebraea vertit Hieron.: _Quoniam contra Deum est manus eorum._","en":"Cod. 86. Aquila's reading seems to be defective, perhaps to be supplied thus: ὅτι ἔστιν ἐπὶ ἰσχυρὸν χ. αὐτοῦ (or αὐτῶν), just as Hieron. renders the Hebrew: _For their hand is against God._"},"1006.1.3":{"la":"Syro-hex. ܗܠܝܢ ܕܫܪܟܐ ܘܡܥܫܩܝܢ[?] ܗܘܘ܀ In textu obelus est in Syro-hex.","en":"Syro-hex. ܗܠܝܢ ܕܫܪܟܐ ܘܡܥܫܩܝܢ[?] ܗܘܘ܀ In the text the obelus is in Syro-hex."},"1006.1.4":{"la":"Sic in textu Syro-hex. Copula deest in Comp., Ald., Codd. III, XII, 22, 26, 36, aliis, et Hieron.","en":"Thus in the text Syro-hex. The copula is missing in Comp., Ald., Codd. III, XII, 22, 26, 36, and others, and Hieron."},"1006.1.5":{"la":"Syro-hex. ܐ. ܐܝܟܢܐ ܢܬܦܢܐ[?] ܠܝ ܠܫܒ̈ܒܐ[?]܀ ܣ. ܐܝܟܢܐ ܢܦܢܐ ܠܝ ܠܡܬܦܢܝܘ܀ ܬ. ܐܝܟܢܐ ܢܙܝܥܝܘܗܝ ܠܡܬܦܢܝܘ܀ (Graecis nostris non multum tribuimus. Formam ܐܬܦܢܝ in Ethpaal semel tantum reperire potuimus Dan. iv. 32, ubi in Graeco est ἀπεδόθη. Ad Sym. et Theod. formam ܠܡܬܦܢܝܘ in Ethpeel, quae ἐπιστρέψαι vel ἐπιστραφῆναι sonat, in versione reddidimus. In textu τοῦ ἐπιστρέψαι commendant Codd. 62, 147.)","en":"Syro-hex. ܐ. ܐܝܟܢܐ ܢܬܦܢܐ[?] ܠܝ ܠܫܒ̈ܒܐ[?]܀ ܣ. ܐܝܟܢܐ ܢܦܢܐ ܠܝ ܠܡܬܦܢܝܘ܀ ܬ. ܐܝܟܢܐ ܢܙܝܥܝܘܗܝ ܠܡܬܦܢܝܘ܀ (We do not attach much weight to our Greek. The form ܐܬܦܢܝ in the Ethpaal we could find only once, Dan. iv. 32, where the Greek has ἀπεδόθη. For Sym. and Theod. we have rendered in the version the form ܠܡܬܦܢܝܘ in the Ethpeel, which means ἐπιστρέψαι or ἐπιστραφῆναι. In the text τοῦ ἐπιστρέψαι is supported by Codd. 62, 147.)"},"1006.1.6":{"la":"Idem: ܐ. ܒܦܘܠܓ̈ܐ܀ ܬ. ܡܦܠܓ܀ ܣ. ܒܕܡܘܬܐ[?] ܗܠܝܢ ܫܒܥܝܢ܀ “Aquilam verbum Hebr. יְחַלֵּק nomine expressisse, nemo sibi persuadebit. Fortasse scripserat ΜΕΡΙΕΙ, quod librarius Graecus demum in ΜΕΡΙϹΙ detorserat.”—_Middeld._ Conjecturae ceteroquin probabili obstat, quod μερὶς Nostro constanter sonat ܡܢܬܐ.","en":"The same: ܐ. ܒܦܘܠܓ̈ܐ܀ ܬ. ܡܦܠܓ܀ ܣ. ܒܕܡܘܬܐ[?] ܗܠܝܢ ܫܒܥܝܢ܀ “No one will persuade himself that Aquila expressed the Hebr. verb יְחַלֵּק by a noun. Perhaps he had written ΜΕΡΙΕΙ, which a Greek copyist then twisted into ΜΕΡΙϹΙ.”—_Middeld._ An otherwise probable conjecture, against which stands the fact that μερὶς is constantly ܡܢܬܐ in our translator."},"1006.1.7":{"la":"Cod. 86 (cum ἐν τροπᾶς pro ἐντροπάς). Hieron.: “_Ne loquamini_, inquit, _loquentes;_ pro quo interpretatus est Aq.: _ne stilletis stillantes._” Cf. Hex. ad Amos vii. 16.","en":"Cod. 86 (with ἐν τροπᾶς for ἐντροπάς). Hieron.: “_Speak not_, he says, _ye who speak;_ for which Aq. rendered: _drop not, ye who drop._” Cf. Hex. on Amos vii. 16."},"1006.1.8":{"la":"Cod. 86. (Waltonus exscripsit ἐπιτιμῶντες, invito cod. Deinde in Hexaplis Montefalconii, tam Graecis quam Latinis, male abest τούτους.) “Verbum נטף, quod in specie de prophetarum sermonibus dicitur, ut Amos vii. 16. Mich. ii. 11, in I et IV conjugatione apud Arabes significat etiam _accusare, reprehendere_, quod sane faciebant veri Dei prophetae, adversus impios istos homines loquentes. Atque haec significatio elegantem sensum facit: _Nolite nos reprehendere, dicunt isti nos reprehendentes._”—_Dathius._","en":"Cod. 86. (Walton transcribed ἐπιτιμῶντες, against the codex. Moreover, in Montfaucon's Hexapla, both Greek and Latin, τούτους is wrongly missing.) “The verb נטף, which is used specifically"},"1007.0.9":{"la":"Cod. 86, ubi ἐνθέως scriptum. Syro-hex. affert: ܐ. ܬ. ܠܐ ܗܘܐ ܕܡܚܫܒܬܐ ܡܛܝܒܝܢ ܥܡܗ ܡܢ ܠܐܘܪܚܐ ܬܪܝܨܐ[?] ܡܗܠܟܘ܀, quae Graece sonant: Ἀ. Θ. οὐχὶ λογισμοῦ ἀγαθύνουσι κ. τ. ἑ.; ubi λογισμοῦ est scribae error, ut videtur, pro λόγοι μου.","en":"Cod. 86, where ἐνθέως is written. Syro-hex. cites: ܐ. ܬ. ܠܐ ܗܘܐ ܕܡܚܫܒܬܐ ܡܛܝܒܝܢ ܥܡܗ ܡܢ ܠܐܘܪܚܐ ܬܪܝܨܐ[?] ܡܗܠܟܘ܀, which in Greek is: Ἀ. Θ. οὐχὶ λογισμοῦ ἀγαθύνουσι κ. τ. ἑ.; where λογισμοῦ is, as it seems, a scribal error for λόγοι μου."},"1007.0.10":{"la":"Syro-hex. ܣ. ܕܠܡܐ ܠܐ ܡ̈ܠܝ ܕܝܠܝ ܡܛܝ̈ܒܢ[?] ܠܓܒܪܐ[?]: ܠܗܘ ܕܬܪܝܨܐܝܬ ܡܬܗܦܟ܀","en":"Syro-hex. ܣ. ܕܠܡܐ ܠܐ ܡ̈ܠܝ ܕܝܠܝ ܡܛܝ̈ܒܢ[?] ܠܓܒܪܐ[?]: ܠܗܘ ܕܬܪܝܨܐܝܬ ܡܬܗܦܟ܀"},"1007.0.11":{"la":"Cod. 86, non, ut Waltonus prave exscripsit, καὶ συναντῶν. (Forma συναντίζω defendit ejusdem interpretis συνάντισμα in Hex. ad Deut. xxiii. 10, a Schleusnero in _Nov. Thes._ s. v. male sollicitatum.)","en":"Cod. 86, not, as Walton wrongly transcribed, καὶ συναντῶν. (The form συναντίζω supports the same translator's συνάντισμα in Hex. on Deut. xxiii. 10, wrongly called into question by Schleusner in _Nov. Thes._ s. v.)"},"1007.0.12":{"la":"Hieron.: “Quia verbum MUL et _contrarium_, et _diem hesternum_ sonat, Sym. apertius transtulit, ut diceret: _Ante unam diem populus meus quasi inimicus restitit._” Cod. 86 affert: Σ. πρὸ μιᾶς δὲ ὁ λ. μου.","en":"Hieron.: “Since the word MUL means both _opposite_ and _yesterday_, Sym. translated more plainly, so as to say: _One day before, my people stood up as an enemy._” Cod. 86 cites: Σ. πρὸ μιᾶς δὲ ὁ λ. μου."},"1007.0.13":{"la":"Syro-hex. ܣ. ܡܢ ܡܐܢ̈ܐ ܕܠܒܘܫܐ ܐܫܠܚܬܘܢ ܠܗܠܝܢ ܕܥܒܪܝܢ ܐܘܪܚܐ ܕܠܐ ܡܪܢܝܢܘܬܐ[?] ܡܢ ܩܪܒܐ܀ (In textu obelus est in Syro-hex.)","en":"Syro-hex. ܣ. ܡܢ ܡܐܢ̈ܐ ܕܠܒܘܫܐ ܐܫܠܚܬܘܢ ܠܗܠܝܢ ܕܥܒܪܝܢ ܐܘܪܚܐ ܕܠܐ ܡܪܢܝܢܘܬܐ[?] ܡܢ ܩܪܒܐ܀ (In the text the obelus is in Syro-hex.)"},"1007.0.14":{"la":"Idem.","en":"The same."},"1007.0.15":{"la":"Idem: ܐ. ܡܬܟܪܟܢܐ ܐܝܟ ܓܙܪܐ[?] ܒܡܨܥܬܐ ܕܟܢܘܫܬܐ ܕܝܠܗ܀ ܣ. ܬ. ܐܝܟ ܡܪ̈ܥܝܬܐ[?] ܒܚܣܢܐ. ܐܝܟ ܓܙܪܐ ܒܡܨܥܬܐ ܕܡܕܒܪܐ܀ “Aquilae ܡܬܟܪܟܢܐ mihi obscurum, aliorum studiis trado. Neque verba _congregationis_ [vox Graece sonat συστροφὴ, συνέδριον, σύστημα, σύνοδος, sim.] _suae_, ad Hebr. הַדָּבְרוֹ pertinentia, satis intelligo.”—_Middeld._ Hieron. Hebraeum בָּצְרָה vertit, _in ovili;_ Chaldaeus בְּגוֹ חוּטְרָא, _in medio ovilis;_ quae nescio an cum tenebricosa Aquilae versione conferri possint.","en":"The same: ܐ. ܡܬܟܪܟܢܐ ܐܝܟ ܓܙܪܐ[?] ܒܡܨܥܬܐ ܕܟܢܘܫܬܐ ܕܝܠܗ܀ ܣ. ܬ. ܐܝܟ ܡܪ̈ܥܝܬܐ[?] ܒܚܣܢܐ. ܐܝܟ ܓܙܪܐ ܒܡܨܥܬܐ ܕܡܕܒܪܐ܀ “Aquila's ܡܬܟܪܟܢܐ is obscure to me; I hand it over to the studies of others. Nor do I sufficiently understand the words _of his congregation_ [the word is in Greek συστροφὴ, συνέδριον, σύστημα, σύνοδος, and the like], belonging to the Hebr. הַדָּבְרוֹ.”—_Middeld._ Hieron. renders the Hebrew בָּצְרָה, _in the sheepfold;_ the Chaldee בְּגוֹ חוּטְרָא, _in the midst of the sheepfold;_ whether these can be compared with Aquila's obscure version I do not know."},"1007.0.16":{"la":"Sic Comp., Ald., Codd. 22 (cum κοπῆς), 23, 42, 51 (ut 22), alii, Hieron., Syro-hex.","en":"Thus Comp., Ald., Codd. 22 (with κοπῆς), 23, 42, 51 (as 22), and others, Hieron., Syro-hex."},"1007.0.17":{"la":"Syro-hex. ܐ. ܬ. ܣܠܩ܀ ܣ. ܢܣܩ ܗܘ ܕܦܣܩ܀","en":"Syro-hex. ܐ. ܬ. ܣܠܩ܀ ܣ. ܢܣܩ ܗܘ ܕܦܣܩ܀"},"1007.0.18":{"la":"Syro-hex. Idem in marg. char. med.: “Hic obelus (ܫܘܦܕܐ[?]) non positus est in Hexaplis.” Hieron. pingit: ÷ _subito_ :. Vox deest in Comp., Ald., Codd. 87*, 91, aliis.","en":"Syro-hex. The same in the margin in medium characters: “This obelus (ܫܘܦܕܐ[?]) is not placed in the Hexapla.” Hieron. writes: ÷ _suddenly_ :. The word is missing in Comp., Ald., Codd. 87*, 91, and others."},"1007.1.1":{"la":"Syro-hex. (cum indice ad αἱ ἀρχαὶ male appicto): ܐ. ܬ. ܪܫܐ ܕܒܝܬܐ܀ ܣ. ܩ̈ܕܡܝܐ[?]܀ Hieron.: “Pro _reliquis domus Israel_, exceptis LXX, omnes _duces domus Israel_, transtulerunt.”","en":"Syro-hex. (with the index wrongly attached to αἱ ἀρχαὶ): ܐ. ܬ. ܪܫܐ ܕܒܝܬܐ܀ ܣ. ܩ̈ܕܡܝܐ[?]܀ Hieron.: “For _the remnant of the house of Israel_, all except the LXX translated _the leaders of the house of Israel_.”"},"1007.1.2":{"la":"Syro-hex. ܣ. ܐܘ ܠܐ ܕܝܠܟܘܢ܀","en":"Syro-hex. ܣ. ܐܘ ܠܐ ܕܝܠܟܘܢ܀"},"1007.1.3":{"la":"Idem: ܣ. ܢܓܥܘܢ܀ ܐ. ܐܝܟ ܗܠܝܢ ܫܒܥܝܢ܀","en":"The same: ܣ. ܢܓܥܘܢ܀ ܐ. ܐܝܟ ܗܠܝܢ ܫܒܥܝܢ܀"},"1007.1.4":{"la":"Idem: ܣ. ܐܠܐ ܢܛܫܐ܀","en":"The same: ܣ. ܐܠܐ ܢܛܫܐ܀"},"1007.1.5":{"la":"Sic cum obelo Syro-hex. Reprobant ἐπ’ αὐτοὺς Comp., Ald., Codd. 87*, 97, alii, et Hieron.","en":"Thus with the obelus Syro-hex. ἐπ’ αὐτοὺς is rejected by Comp., Ald., Codd. 87*, 97, and others, and Hieron."},"1008.0.6":{"la":"Syro-hex. ܐ. ܐܒܐܫܘ ܥܒ̈ܕܐ ܕܝܠܗܘܢ܀ ܣ. ܗܘܘ ܒܝܫܐ ܡܢ[?] ܥܒ̈ܕܐ܀ ܬ. ܗܘܘ ܒܝܫܐ ܡܛܠ ܥܒ̈ܕܐ ܕܝܠܗܘܢ܀","en":"Syro-hex. ܐ. ܐܒܐܫܘ ܥܒ̈ܕܐ ܕܝܠܗܘܢ܀ ܣ. ܗܘܘ ܒܝܫܐ ܡܢ[?] ܥܒ̈ܕܐ܀ ܬ. ܗܘܘ ܒܝܫܐ ܡܛܠ ܥܒ̈ܕܐ ܕܝܠܗܘܢ܀"},"1008.0.7":{"la":"Sic Comp., Ald., Codd. XII (in marg.), 22, 42, 51, alii, Hieron., Syro-hex.","en":"Thus Comp., Ald., Codd. XII (in the margin), 22, 42, 51, and others, Hieron., Syro-hex."},"1008.0.8":{"la":"Syro-hex. ܐ. ܬ. ܘܠܐ ܝܗܒܘ ܥܠ ܦܘܡܐ ܕܝܠܗܘܢ. ܩܕܫܘ ܥܠܘܗܝ ܩܪܒܐ܀ ܣ. ܥܠ ܗܢܘܢ ܕܝܢ ܕܠܐ ܝܗܒܝܢ ܒܦܘܡܐ ܕܝܠܗܘܢ ܡܬܗܪܗܪܝܢ[?] ܗܘܘ ܠܩܪ̈ܒܐ܀ Ad Symmachum Middeld. vertit, _contendebant_ εἰς πολέμους, a radice ܗܪ, unde ܐܬܗܪ ܥܡ[?], ἐρίζεις 4 Reg. xiv. 10, et ܗܪܝܐ[?], ἐρεθιστὴς Deut. xxi. 18, teste Masio. Nos ad Chaldaicum הַרְהֵר, _cogitavit_ (vid. Dan. iv. 2), confugimus, unde ܗܪܗܪܐ, _phantasma, imaginatio_, sine exemplis attulit Castell.","en":"Syro-hex. ܐ. ܬ. ܘܠܐ ܝܗܒܘ ܥܠ ܦܘܡܐ ܕܝܠܗܘܢ. ܩܕܫܘ ܥܠܘܗܝ ܩܪܒܐ܀ ܣ. ܥܠ ܗܢܘܢ ܕܝܢ ܕܠܐ ܝܗܒܝܢ ܒܦܘܡܐ ܕܝܠܗܘܢ ܡܬܗܪܗܪܝܢ[?] ܗܘܘ ܠܩܪ̈ܒܐ܀ For Symmachus Middeld. renders _they contended_ εἰς πολέμους, from the root ܗܪ, whence ܐܬܗܪ ܥܡ[?], ἐρίζεις 4 Reg. xiv. 10, and ܗܪܝܐ[?], ἐρεθιστὴς Deut. xxi. 18, on the testimony of Masius. We have recourse to the Chaldee הַרְהֵר, _he thought_ (see Dan. iv. 2), whence ܗܪܗܪܐ, _phantasm, imagination_, which Castell gave without examples."},"1008.0.9":{"la":"Syro-hex. ܣ. ܐܝܟܢܐ ܕܠܐ ܬܚܙܘܢ܀","en":"Syro-hex. ܣ. ܐܝܟܢܐ ܕܠܐ ܬܚܙܘܢ܀"},"1008.0.10":{"la":"Idem: ܣ. ܐܝܟܢܐ ܕܠܐ ܬܩܣܡܘܢ܀","en":"The same: ܣ. ܐܝܟܢܐ ܕܠܐ ܬܩܣܡܘܢ܀"},"1008.0.11":{"la":"Idem: ܣ. ܘܡܬܥܛܦܝܢ ܥܠ ܣܦܘ̈ܬܗܘܢ ܟܠܗܘܢ܀","en":"The same: ܣ. ܘܡܬܥܛܦܝܢ ܥܠ ܣܦܘ̈ܬܗܘܢ ܟܠܗܘܢ܀"},"1008.0.12":{"la":"Idem: ܬ. ܡܛܠ ܕܠܝܬ ܦܘܢܝ ܦܬܓܡܐ ܕܐܠܘܐܝܡ. Cf. ad Cap. vi. 8.","en":"The same: ܬ. ܡܛܠ ܕܠܝܬ ܦܘܢܝ ܦܬܓܡܐ ܕܐܠܘܐܝܡ. Cf. on Cap. vi. 8."},"1008.0.13":{"la":"Idem: ܣ. ܡܛܠ ܕܠܝܬ ܗܘܐ ܦܘܢܝ ܦܬܓܡܐ ܕܐܠܗܐ܀","en":"The same: ܣ. ܡܛܠ ܕܠܝܬ ܗܘܐ ܦܘܢܝ ܦܬܓܡܐ ܕܐܠܗܐ܀"},"1008.0.14":{"la":"Sic Codd. 22, 51, alii, et Chrysost. Opp. T. X, p. 610 A.","en":"Thus Codd. 22, 51, and others, and Chrysost. Opp. T. X, p. 610 A."},"1008.0.15":{"la":"Syro-hex. ܣ. ܐܠܐ ܐܢܐ ܐܬܡܠܝܬ. ܡܢ ܚܝܠܐ ܕܪܘܚܐ ܘܕܕܝܢܐ ܘܡܫܠܛܢܘܬܐ܀ (Syrus legisse videtur ἀλλὰ μὲν ἐγὼ, ut apud Chrysost. l. c. ante nos edebatur.) Cod. 86 affert: Σ. ἀλλὰ μὴν (in cod. ἀλαμὴν) ἐγὼ ἐνεπλήσθην ἰσχύος.","en":"Syro-hex. ܣ. ܐܠܐ ܐܢܐ ܐܬܡܠܝܬ. ܡܢ ܚܝܠܐ ܕܪܘܚܐ ܘܕܕܝܢܐ ܘܡܫܠܛܢܘܬܐ܀ (The Syrian seems to have read ἀλλὰ μὲν ἐγὼ, as was printed in Chrysost. l. c. before us.) Cod. 86 cites: Σ. ἀλλὰ μὴν (in the codex ἀλαμὴν) ἐγὼ ἐνεπλήσθην ἰσχύος."},"1008.0.16":{"la":"Syro-hex. Theodotioni continuat: ܐܬܟܠܝ. ܐܢܐ ܐܝܬܝ. ܐܬܡܠܝܬ ܚܝܠܐ ܕܪܘܚܐ܀ Interpres, ut videtur, particulam אוּלָם pro derivativo verbi אָלַם, _ligavit_, habuit, quod in Niphal commutatur cum συνεσχέθη Ezech. xxxiii. 22 in LXX.","en":"Syro-hex. continues for Theodotion: ܐܬܟܠܝ. ܐܢܐ ܐܝܬܝ. ܐܬܡܠܝܬ ܚܝܠܐ ܕܪܘܚܐ܀ The translator, as it seems, took the particle אוּלָם for a derivative of the verb אָלַם, _he bound_, which in the Niphal alternates with συνεσχέθη Ezech. xxxiii. 22 in the LXX."},"1008.0.17":{"la":"Syro-hex. ܐ. ܬ. ܡܫ̈ܠܛܢܐ܀ (Vox Syriaca commutatur cum ἐξουσιάζοντες Eccles. vii. 20; cum δυναστεύοντες Hex. ad Gen. vi. 3.)","en":"Syro-hex. ܐ. ܬ. ܡܫ̈ܠܛܢܐ܀ (The Syriac word alternates with ἐξουσιάζοντες Eccles. vii. 20; with δυναστεύοντες Hex. on Gen. vi. 3.)"},"1008.0.18":{"la":"Idem: ܐ. ܬ. ܡܢܗܪܝܢ ܗܘܘ܀","en":"The same: ܐ. ܬ. ܡܢܗܪܝܢ ܗܘܘ܀"},"1008.0.19":{"la":"Idem (cum ※ ܘܢܒ̈ܝܝܗ̇[?] ↙, ubi litera minio superscripta est ܗ̇[?], non ܗ[?]). Pronomen est in libris omnibus.","en":"The same (with ※ ܘܢܒ̈ܝܝܗ̇[?] ↙, where the letter written above in red is ܗ̇[?], not ܗ[?]). The pronoun is in all the books."},"1008.0.20":{"la":"Idem: ܐ. ܐܝܟ ܓܘܪܐ[?]܀ ܣ. ܠܬܠܐ܀ ܬ. ܠܚܘܪܒܐ܀ Ad Aquilam cf. Hex. ad Psal. lxxviii. 1. Jerem. xxvi. 18. Mich. iii. 12.","en":"The same: ܐ. ܐܝܟ ܓܘܪܐ[?]܀ ܣ. ܠܬܠܐ܀ ܬ. ܠܚܘܪܒܐ܀ On Aquila cf. Hex. on Psal. lxxviii. 1. Jerem. xxvi. 18. Mich. iii. 12."},"1008.0.21":{"la":"Euseb. in Dem. Evang. p. 406: Ὁ γοῦν Ἀκύλας φησί· διὰ τοῦτο—λιθολογηθήσεται· ὑπὸ γὰρ ἀλλοφύλων ἀνδρῶν κατοικισθεῖσα εἰσέτι καὶ σήμερον λιθολογεῖται, πάντων καθ’ ἡμᾶς αὐτοὺς τῶν τὴν πόλιν οἰκούντων τοὺς ἀπὸ τῆς πτώσεως αὐτῆς λίθους ἀναλεγομένων εἴς τε τὰ ἴδια καὶ κοινὰ καὶ δημόσια οἰκοδομήματα.","en":"Euseb. in Dem. Evang. p. 406: Ὁ γοῦν Ἀκύλας φησί· διὰ τοῦτο—λιθολογηθήσεται· ὑπὸ γὰρ ἀλλοφύλων ἀνδρῶν κατοικισθεῖσα εἰσέτι καὶ σήμερον λιθολογεῖται, πάντων καθ’ ἡμᾶς αὐτοὺς τῶν τὴν πόλιν οἰκούντων τοὺς ἀπὸ τῆς πτώσεως αὐτῆς λίθους ἀναλεγομένων εἴς τε τὰ ἴδια καὶ κοινὰ καὶ δημόσια οἰκοδομήματα."},"1008.0.22":{"la":"Syro-hex. ܣ. ܠܪܘܡܐ ܕܥܒܐ܀ ܬ. ܠܓܒܠܬܐ ܕܥܒܐ܀ Cf. Hex. ad Jerem. xxvi. 18.","en":"Syro-hex. ܣ. ܠܪܘܡܐ ܕܥܒܐ܀ ܬ. ܠܓܒܠܬܐ ܕܥܒܐ܀ Cf. Hex. on Jerem. xxvi. 18."},"1008.0.23":{"la":"Syro-hex.","en":"Syro-hex."},"1009.1.1":{"la":"Sic Comp. (sine τοῦ), Codd. 22, 36, alii.","en":"Thus Comp. (without τοῦ), Codd. 22, 36, and others."},"1009.1.2":{"la":"Syro-hex. ܓ. ܕܐܠܗܐ܀","en":"Syro-hex. ܓ. ܕܐܠܗܐ܀"},"1009.1.3":{"la":"Idem: ܣ. ܘܢܬܟܢܫܘܢ܀ “Justin. M. [p. 369] locum hunc sic citat: ἕτοιμον ἐπ’ ἄκρου τῶν ὀρέων, ἐπηρμένον αὐτὸ ὑπὲρ τοὺς βουνούς· [וְנִשָּׂא הוּא מִגְּבָעוֹת] καὶ ποταμὸν θήσονται [fort. ποταμωθήσονται (וְנָהֲרוּ), coll. Hex. ad Jerem. li. 44] ἐπ’ αὐτῷ λαοί.”—_Nobil._ Mox v. 2 pro καὶ δείξουσιν ἡμῖν idem citat καὶ φωτιοῦσιν ἡμᾶς (וְיֹרֵנוּ).","en":"The same: ܣ. ܘܢܬܟܢܫܘܢ܀ “Justin. M. [p. 369] cites this passage thus: ἕτοιμον ἐπ’ ἄκρου τῶν ὀρέων, ἐπηρμένον αὐτὸ ὑπὲρ τοὺς βουνούς· [וְנִשָּׂא הוּא מִגְּבָעוֹת] καὶ ποταμὸν θήσονται [perhaps ποταμωθήσονται (וְנָהֲרוּ), comparing Hex. on Jerem. li. 44] ἐπ’ αὐτῷ λαοί.”—_Nobil._ Next, in v. 2, for καὶ δείξουσιν ἡμῖν the same cites καὶ φωτιοῦσιν ἡμᾶς (וְיֹרֵנוּ)."},"1009.1.4":{"la":"Idem: ܣ. ܡܢ ܨܗܝܘܢ ܓܝܪ܀","en":"The same: ܣ. ܡܢ ܨܗܝܘܢ ܓܝܪ܀"},"1009.1.5":{"la":"Idem: ܐ. ܣ. ܒܝܢܬ܀","en":"The same: ܐ. ܣ. ܒܝܢܬ܀"},"1009.1.6":{"la":"Sic Codd. III, XII (in textu), 26 (cum ξιβύνας), 40, 49, alii, et Justin. M. l. c. Syro-hex. vertit ܪ̈ܘܡܚܐ[?], quae vox commutatur cum ζιβύνη Judith i. [15] in Syro-hex., necnon in lectione Symmachi ad Jos. viii. [26?], teste Masio in _Syr. Pecul._ p. 25. Cf. ad Cap. v. 6.","en":"Thus Codd. III, XII (in the text), 26 (with ξιβύνας), 40, 49, and others, and Justin. M. l. c. Syro-hex. renders ܪ̈ܘܡܚܐ[?], a word which alternates with ζιβύνη Judith i. [15] in Syro-hex., and also in a reading of Symmachus on Jos. viii. [26?], on the testimony of Masius in _Syr. Pecul._ p. 25. Cf. on Cap. v. 6."},"1009.1.7":{"la":"Cod. Jes.","en":"Cod. Jes."},"1009.1.8":{"la":"Syro-hex. Vox ὑποκάτω legitur in libris omnibus. Paulo ante pro καὶ ἀναπαύσεται ἕκαστος Justin. M. l. c. affert: καὶ καθίσεται ἀνήρ (וְיָשְׁבוּ אִישׁ); et mox τῶν δυνάμεων pro παντοκράτορος.","en":"Syro-hex. The word ὑποκάτω is read in all the books. A little before, for καὶ ἀναπαύσεται ἕκαστος Justin. M. l. c. cites: καὶ καθίσεται ἀνήρ (וְיָשְׁבוּ אִישׁ); and next τῶν δυνάμεων for παντοκράτορος."},"1009.1.9":{"la":"Syro-hex. in marg. sine nom. ܒܫܡܗ ܕܐܠܗܐ܀ Justin. M. l. c.: ἐν ὀνόματι θεῶν αὐτῶν. Idem integrum v. 6 sic citat: καὶ ἔσται ἐν τῇ ἡμέρᾳ ἐκείνῃ, συνάξω τὴν ἐκτεθλιμμένην (הַצֹּלֵעָה, _claudicantem_), καὶ τὴν ἐξωσμένην ἀθροίσω (אֲקַבְּצָה), καὶ ἣν ἐκάκωσα (הֲרֵעֹתִי).","en":"Syro-hex. in the margin without a name ܒܫܡܗ ܕܐܠܗܐ܀ Justin. M. l. c.: ἐν ὀνόματι θεῶν αὐτῶν. The same cites the whole of v. 6 thus: καὶ ἔσται ἐν τῇ ἡμέρᾳ ἐκείνῃ, συνάξω τὴν ἐκτεθλιμμένην (הַצֹּלֵעָה, _her that halteth_), καὶ τὴν ἐξωσμένην ἀθροίσω (אֲקַבְּצָה), καὶ ἣν ἐκάκωσα (הֲרֵעֹתִי)."},"1009.1.10":{"la":"Syro-hex. ܠܫܪܟܢܐ[?] ÷ ܕܡܟܬܪ ↙. Solus Cod. XII in marg. addit διαμένον. Justin. M. l. c.: καὶ θήσω τὴν ἐκτεθλιμμένην εἰς ὑπόλειμμα, καὶ τὴν ἐκπεπιεσμένην (הַנַּהֲלָאָה, _procul remotam_) εἰς ἔθνος ἰσχυρόν.","en":"Syro-hex. ܠܫܪܟܢܐ[?] ÷ ܕܡܟܬܪ ↙. Only Cod. XII adds διαμένον in the margin. Justin. M. l. c.: καὶ θήσω τὴν ἐκτεθλιμμένην εἰς ὑπόλειμμα, καὶ τὴν ἐκπεπιεσμένην (הַנַּהֲלָאָה, _her that was cast far off_) εἰς ἔθνος ἰσχυρόν."},"1009.1.11":{"la":"Cod. 86. Syro-hex. affert: ܐ. ܚܫܘܟܐ܀ Etiam Hieron. vertit _nebulosa_, h. e. אֹפֶל. Cum Symmacho facit Chaldaeus, דְּטָמִיר, _absconditus_, vertens.","en":"Cod. 86. Syro-hex. cites: ܐ. ܚܫܘܟܐ܀ Hieron. too renders _cloudy_, i.e. אֹפֶל. With Symmachus agrees the Chaldee, rendering דְּטָמִיר, _hidden_."},"1009.1.12":{"la":"Hieron.: “Et haec turris _filiae_ est _Sion_, sive, ut Sym. vertit in Graecum, ipsa est _filia Sion._” Quem locum non ceperunt, qui ante nos lectiones hexaplares expenderunt.","en":"Hieron.: “And this tower is _of the daughter of Sion_, or, as Sym. rendered into Greek, it is _the daughter of Sion_ herself.” A passage not understood by those who examined the hexaplar readings before us."},"1009.1.13":{"la":"Syro-hex. ܐ. ܥܕܡܐ܀ ܬ. ܥܠܝܟܝ܀","en":"Syro-hex. ܐ. ܥܕܡܐ܀ ܬ. ܥܠܝܟܝ܀"},"1009.1.14":{"la":"Sic Syro-hex., qui notat: “Hic obelus non positus erat in Hexaplis.” Hieron.: “Quod autem in quibusdam libris legitur: _Et ingredietur principatus primus regnum filiae Sion_, et _de Babylone_, sciamus additum esse, quia nec in Hebraeo, nec apud alios habetur interpretes.”","en":"Thus Syro-hex., which notes: “This obelus was not placed in the Hexapla.” Hieron.: “But what is read in some books: _And the first dominion shall come into the kingdom of the daughter of Sion_, and _from Babylon_, let us know that it was added, because it is found neither in the Hebrew nor in the other translators.”"},"1009.1.15":{"la":"Syro-hex. ܐ. ܐܒܐܫܬܝ܀","en":"Syro-hex. ܐ. ܐܒܐܫܬܝ܀"},"1009.1.16":{"la":"Idem: ܗܠܝܢ ܕܫܪܟܐ ܠܐ ܐܝܬ ܠܟܝ܀","en":"The same: ܗܠܝܢ ܕܫܪܟܐ ܠܐ ܐܝܬ ܠܟܝ܀"},"1009.1.17":{"la":"Idem in marg. sine nom. ܡܠܟܐ ܕܝܠܟܝ܀ Cf. Hex. ad Jesai. ix. 6.","en":"The same in the margin without a name ܡܠܟܐ ܕܝܠܟܝ܀ Cf. Hex. on Jesai. ix. 6."},"1009.1.18":{"la":"Sic Syro-hex., qui notat ut supra. Verba, καὶ ἔγγιζε, non agnoscunt Comp., Codd. III, 87*, 91, alii, Hieron.","en":"Thus Syro-hex., which notes as above. The words καὶ ἔγγιζε are not recognized by Comp., Codd. III, 87*, 91, and others, Hieron."},"1009.1.19":{"la":"Syro-hex. in marg. sine nom. ܐܬܡܬܚܝ܀ Vox Graeca ponitur de _summa virium_ aut _vocis contentione_, quae notio huic loco satis apta est.","en":"Syro-hex. in the margin without a name ܐܬܡܬܚܝ܀ The Greek word is used of _the utmost exertion of strength_ or _straining of the voice_, a notion sufficiently suited to this passage."},"1009.1.20":{"la":"Sic Ald., Codd. 22, 36, 51, alii, etiam Cod. 86, teste Waltono, invitis schedis Bodleianis, ubi huic libro tribuitur ἐπισυναχθήσονται (in marg. ἀχθήσεται).","en":"Thus Ald., Codd. 22, 36, 51, and others, also Cod. 86, on the testimony of Walton, against the Bodleian sheets, where ἐπισυναχθήσονται (in the margin ἀχθήσεται) is attributed to this book."},"1009.1.21":{"la":"Cod. 86 affert: Σ. συναχθήσεται. συνελέγησαν. Lectionem anonymam Aquilae vindicavimus, coll. Hex. ad Psal. xxxiv. 15.","en":"Cod. 86 cites: Σ. συναχθήσεται. συνελέγησαν. We have claimed the anonymous reading for Aquila, comparing Hex. on Psal. xxxiv. 15."},"1009.1.22":{"la":"Syro-hex. ܐ. ܬܦܠ ܒܚܡܬܐ܀ ܣ. ܬܬܚܝܒ܀ Cf. Hex. ad Psal. cv. 38. Jerem. iii. 2.","en":"Syro-hex. ܐ. ܬܦܠ ܒܚܡܬܐ܀ ܣ. ܬܬܚܝܒ܀ Cf. Hex. on Psal. cv. 38. Jerem. iii. 2."},"1010.0.23":{"la":"Syro-hex. ܐ. ܣ. ܐܝܟ ܥܘܪܐ܀ ܬ. ܐܝܟ ܩܫܐ ܕܚܩܠܐ܀ Ad Aquilam cf. Hex. ad Dan. ii. 35. Periphrasis ܩܫܐ ܕܚܩܠܐ ponitur pro καλάμη Amos ii. 13.","en":"Syro-hex. ܐ. ܣ. ܐܝܟ ܥܘܪܐ܀ ܬ. ܐܝܟ ܩܫܐ ܕܚܩܠܐ܀ On Aquila cf. Hex. on Dan. ii. 35. The periphrasis ܩܫܐ ܕܚܩܠܐ is used for καλάμη Amos ii. 13."},"1010.0.24":{"la":"Sic Codd. III, XII, 40, 42, alii. Hieron. _comminues._","en":"Thus Codd. III, XII, 40, 42, and others. Hieron. _thou shalt break in pieces._"},"1010.0.25":{"la":"Sic Syro-hex., et sine obelo Ald., Codd. 23, 49, 62, alii; necnon (cum καταπατήσεις pro κατατήξεις) Codd. 22, 36, alii.","en":"Thus Syro-hex., and without the obelus Ald., Codd. 23, 49, 62, and others; also (with καταπατήσεις for κατατήξεις) Codd. 22, 36, and others."},"1010.0.26":{"la":"Cod. 86.","en":"Cod. 86."},"1010.0.27":{"la":"Hieron.: “Theod. pro _multitudine, munera_ transtulit; Quinta ed. _emolumentum_, id est, ὠφέλειαν; Sym. _lucrum_, id est, τὸ κέρδος αὐτῶν.” Syro-hex. affert: Σ. τὸ κέρδος (ܝܘܬܪܢܐ).","en":"Hieron.: “Theod. for _multitude_ translated _gifts_; the Fifth ed. _profit_, that is, ὠφέλειαν; Sym. _gain_, that is, τὸ κέρδος αὐτῶν.” Syro-hex. cites: Σ. τὸ κέρδος (ܝܘܬܪܢܐ)."},"1010.0.28":{"la":"Syro-hex.","en":"Syro-hex."},"1010.1.1":{"la":"Syro-hex. ܣ. ܗܫܐ ܢܚܒܠܘܢܟܝ ܒܪܬܐ ܡܬܚܒܫܬܐ[?], cum scholio: ܢܚܒܠܘܢܟܝ ܡܢ ܚ̈ܒܠܐ ܕܡܠܕܐ[?] ܐܦܪ[?]܀ (In textu post θυγάτηρ add. Ἐφραΐμ Codd. III, XII, 26, 36, alii, et Syro-hex.)","en":"Syro-hex. ܣ. ܗܫܐ ܢܚܒܠܘܢܟܝ ܒܪܬܐ ܡܬܚܒܫܬܐ[?], with the scholion: ܢܚܒܠܘܢܟܝ ܡܢ ܚ̈ܒܠܐ ܕܡܠܕܐ[?] ܐܦܪ[?]܀ (In the text after θυγάτηρ Codd. III, XII, 26, 36, and others, and Syro-hex. add Ἐφραΐμ.)"},"1010.1.2":{"la":"Hieron.: “_Nunc vastaberis, filia latronis._ Hoc juxta Hebraicum, cui interpretationi Aq. et Sym. et Theod. et editio Quinta consentiunt.” Quod tamen dictum cum lectione Symmachi Syriaca conciliari nequit.","en":"Hieron.: “_Now thou shalt be laid waste, O daughter of the robber._ This according to the Hebrew, with which rendering Aq. and Sym. and Theod. and the Fifth edition agree.” This statement, however, cannot be reconciled with the Syriac reading of Symmachus."},"1010.1.3":{"la":"Syro-hex. Symmacho continuat: ܡܚܒܫܢܘܬܐ[?] ܐܬܬܣܝܡܬ ܥܠܝܢ.","en":"Syro-hex. continues for Symmachus: ܡܚܒܫܢܘܬܐ[?] ܐܬܬܣܝܡܬ ܥܠܝܢ."},"1010.1.4":{"la":"Cod. 86.","en":"Cod. 86."},"1010.1.5":{"la":"“Trium interpretationes ex Eclogis Joannis Monachi litera X in Cod. Coislin.”—_Montef._ Symmachi lectionem accurate reddidit Syro-hex. ܒܫܒܛܐ ܢܡܚܘܢ ܥܠ ܦܟܐ ܠܕܝܢܐ ܕܐܝܣܪܝܠ܀","en":"“The renderings of the Three from the Eclogae of Joannes Monachus, under the letter X, in the Coislin. Cod.”—_Montef._ Syro-hex. rendered Symmachus' reading exactly: ܒܫܒܛܐ ܢܡܚܘܢ ܥܠ ܦܟܐ ܠܕܝܢܐ ܕܐܝܣܪܝܠ܀"},"1010.1.6":{"la":"Sic Codd. 22, 26, 36, alii. Syrus noster interrogando effert: ܙܥܘܪܬܐ ܐܢܬܝ ܗܘ[?]. Hieron. in Epist. LVII ad Pammach. 8: “Pro, _Nequaquam minima es in ducibus Judae_ (Matth. ii. 6), in LXX legitur: _Modicus es, ut sis in millibus Juda._”","en":"Thus Codd. 22, 26, 36, and others. Our Syrian expresses it as a question: ܙܥܘܪܬܐ ܐܢܬܝ ܗܘ[?]. Hieron. in Epist. LVII to Pammachius 8: “For _Thou art by no means the least among the princes of Judah_ (Matth. ii. 6), in the LXX is read: _Thou art small, to be among the thousands of Judah._”"},"1010.1.7":{"la":"Syro-hex. ܣ. ܕܝܠܗ ܕܝܢ ܕܝܠܕܐ܀ ܬ. ܝܠܕܬ܀","en":"Syro-hex. ܣ. ܕܝܠܗ ܕܝܢ ܕܝܠܕܐ܀ ܬ. ܝܠܕܬ܀"},"1010.1.8":{"la":"Idem.","en":"The same."},"1010.1.9":{"la":"Syro-hex. pingit: ÷ καὶ ὄψεται, καὶ ποιμανεῖ ÷ τὸ π. αὐτοῦ ↙; ubi obelus posterior in initio lineae positus est. Sed metobelum post ὄψεται casu abesse innuit scholium in marg. appictum: “Hi obeli (ܗܠܝܢ ܫܘܦܕ̈ܐ[?]) non positi erant in Hexaplis.” Similiter Cod. Jes. in marg. notat: τὰ ὠβελισμένα εἰς τοὺς δύο τόπους οὐ κεῖνται ἐν τῷ ἑξασελίδῳ.","en":"Syro-hex. writes: ÷ καὶ ὄψεται, καὶ ποιμανεῖ ÷ τὸ π. αὐτοῦ ↙; where the second obelus is placed at the beginning of a line. But that the metobelus after ὄψεται is missing by accident is indicated by the scholion added in the margin: “These obeli (ܗܠܝܢ ܫܘܦܕ̈ܐ[?]) were not placed in the Hexapla.” Similarly Cod. Jes. notes in the margin: τὰ ὠβελισμένα εἰς τοὺς δύο τόπους οὐ κεῖνται ἐν τῷ ἑξασελίδῳ."},"1010.1.10":{"la":"Hieron.: “_Et convertentur_, sive ut melius interpretatus est Sym., _et habitabunt:_ JASUBU enim verbum Hebraicum utrumque significat.”","en":"Hieron.: “_And they shall be converted_, or as Sym. rendered better, _and they shall dwell:_ for the Hebrew word JASUBU signifies both.”"},"1010.1.11":{"la":"Syro-hex. ܣ. ܗܝܕܝܢ ܓܝܪ ܢܬܪܘܪܒ ܥܕܡܐ ܠܚܪܬܗ̇ ܕܐܪܥܐ܀","en":"Syro-hex. ܣ. ܗܝܕܝܢ ܓܝܪ ܢܬܪܘܪܒ ܥܕܡܐ ܠܚܪܬܗ̇ ܕܐܪܥܐ܀"},"1011.0.12":{"la":"Aquilae et Theodotionis lectiones integras exhibet Cod. 86, et inter eas: Σ. ἑπτὰ ποιμένας. Idem separatim affert: δήγματα] Ἀ. καθεσταμένους ἀνθρώπους. Σ. χρηστοὺς (sic) ἀνθρώπων. σήγματα (sic). Syro-hex. ad δήγματα in marg. notat: Ἀ. καθεσταμένους (ܕܐܬܬܩܝܡܘ). Σ. χριστούς (ܡܫܝܚܐ). Θ. ἀρχηγούς (ܪ̈ܫܐ). Denique Hieron. monet: “Ubi nos posuimus _primates homines_, et in Hebraico scriptum est NESICHE ADAM, Sym. interpretatus est _Christos hominum;_ Theod. et Quinta ed., _principes hominum;_ Aq. _graves_ vel _constitutos homines_, id est, καθεσταμένους.” Cf. Hex. ad Ezech. xxxii. 30.","en":"Cod. 86 presents the complete readings of Aquila and Theodotion, and among them: Σ. ἑπτὰ ποιμένας. The same cites separately: δήγματα] Ἀ. καθεσταμένους ἀνθρώπους. Σ. χρηστοὺς (sic) ἀνθρώπων. σήγματα (sic). Syro-hex. notes on δήγματα in the margin: Ἀ. καθεσταμένους (ܕܐܬܬܩܝܡܘ). Σ. χριστούς (ܡܫܝܚܐ). Θ. ἀρχηγούς (ܪ̈ܫܐ). Finally Hieron. advises: “Where we put _principal men_, and in the Hebrew is written NESICHE ADAM, Sym. rendered _anointed ones of men;_ Theod. and the Fifth ed., _princes of men;_ Aq. _weighty_ or _appointed men_, that is, καθεσταμένους.” Cf. Hex. on Ezech. xxxii. 30."},"1011.0.13":{"la":"Hieron.: “Rursum in eo ubi ego et Aq. transtulimus, _in lanceis ejus_, ut subaudiatur _terrae Nemrod_, Sym. vertit, ἐντὸς πυλῶν αὐτῆς, id est, _intra portas ejus;_ Theod. _in portis eorum;_ Quinta ed. ἐν παραξιφίσιν αὐτῶν, quod nos possumus dicere, _in sicis eorum:_ in Hebraeo autem positum est BAPHETHEE.” Praeterea Cod. 86 affert: Σ. ἐντὸς πυλῶν; Syro-hex. autem: ܐ. ܒܪ̈ܘܡܚܝܗ̇[?]܀ ܬ. ܒܬܪ̈ܥܐ܀ (Ad ܪܘܡܚܐ cf. Jerem. vi. 23. Joel iii. 10 in Syro-hex.)","en":"Hieron.: “Again, in the place where I and Aq. translated, _with its lances_, so that _of the land of Nimrod_ is understood, Sym. rendered ἐντὸς πυλῶν αὐτῆς, that is, _within its gates;_ Theod. _in their gates;_ the Fifth ed. ἐν παραξιφίσιν αὐτῶν, which we can call _with their daggers:_ but in the Hebrew is put BAPHETHEE.” Further, Cod. 86 cites: Σ. ἐντὸς πυλῶν; and Syro-hex.: ܐ. ܒܪ̈ܘܡܚܝܗ̇[?]܀ ܬ. ܒܬܪ̈ܥܐ܀ (On ܪܘܡܚܐ cf. Jerem. vi. 23. Joel iii. 10 in Syro-hex.)"},"1011.0.14":{"la":"Hieron.","en":"Hieron."},"1011.0.15":{"la":"Syro-hex. in textu: ܘܠܬܘܩܦܐ[?] ܕܚܣܝܘܬܐ ܒܚܦܝܪܬܐ ܢܦܪܘܩ; in marg. autem char. med. ܗܘ ܦܬܓܡܐ ܕܡܚܣܢܐ[?] ܕܚܣܝܘܬܐ ܒܚܦܝܪܬܐ. ܠܥܠ ܡܢ ܡܬܬܒܥܢܘܬܐ[?] ܐܬܝܗܒܬ[?]. Ineptae interpolationis, quae Syro nostro, ut videtur, propria et peculiaris est, neque originem neque sensum indagare potuimus.","en":"Syro-hex. in the text: ܘܠܬܘܩܦܐ[?] ܕܚܣܝܘܬܐ ܒܚܦܝܪܬܐ ܢܦܪܘܩ; but in the margin in medium characters ܗܘ ܦܬܓܡܐ ܕܡܚܣܢܐ[?] ܕܚܣܝܘܬܐ ܒܚܦܝܪܬܐ. ܠܥܠ ܡܢ ܡܬܬܒܥܢܘܬܐ[?] ܐܬܝܗܒܬ[?]. Of this absurd interpolation, which seems to be proper and peculiar to our Syrian, we have been able to trace neither the origin nor the sense."},"1011.0.16":{"la":"Euseb. in Dem. Evang. p. 81 (cum Θ. pro Σ. Θ.). Cod. 86 affert: Ἀ. ψεκάδες. Θ. νιφετός; et ad ἄγρωστιν: Ἀ. σπόρον. Σ. Θ. χόρτον. Denique Syro-hex. ܐ. ܘܐܝܟ ܢܛ̈ܦܐ ܥܠ ܬܐܕܐ (πόαν)܀ ܣ. ܬ. ܘܐܝܟ ܬܠ̈ܓܐ (νιφετοὶ) ܥܠ ܥܣܒܐ܀ Ad Aq. cf. Hex. ad Psal. xxii. 2.","en":"Euseb. in Dem. Evang. p. 81 (with Θ. for Σ. Θ.). Cod. 86 cites: Ἀ. ψεκάδες. Θ. νιφετός; and on ἄγρωστιν: Ἀ. σπόρον. Σ. Θ. χόρτον. Finally Syro-hex. ܐ. ܘܐܝܟ ܢܛ̈ܦܐ ܥܠ ܬܐܕܐ (πόαν)܀ ܣ. ܬ. ܘܐܝܟ ܬܠ̈ܓܐ (νιφετοὶ) ܥܠ ܥܣܒܐ܀ On Aq. cf. Hex. on Psal. xxii. 2."},"1011.0.17":{"la":"Euseb. ibid. p. 82, ubi editum: καὶ οὐ περὶ υἱοὺς ἀνθρώπων. Emaculavimus juxta Syrum nostrum, qui tribus interpretibus tribuit ܢܣܒܪ. Cf. Hex. ad Psal. xxx. 25. xxxii. 22. cxviii. 49.","en":"Euseb. ibid. p. 82, where it is printed: καὶ οὐ περὶ υἱοὺς ἀνθρώπων. We have corrected it according to our Syrian, who attributes ܢܣܒܪ to the three translators. Cf. Hex. on Psal. xxx. 25. xxxii. 22. cxviii. 49."},"1011.0.18":{"la":"Syro-hex. ܓ. ܕܠܐ ܢܬܬܟܠ ܥܠ ܒܪܢܫܐ. ܘܠܐ ܢܣܒܪ ܠܒܪܗ[?] ܕܐܢܫܐ܀","en":"Syro-hex. ܓ. ܕܠܐ ܢܬܬܟܠ ܥܠ ܒܪܢܫܐ. ܘܠܐ ܢܣܒܪ ܠܒܪܗ[?] ܕܐܢܫܐ܀"},"1011.0.19":{"la":"Cod. 86. Consentit Syro-hex. ܐ. ܘܡܩܨ̈ܡܐ[?]܀ ܣ. ܦܪ̈ܘܫܝ[?] ܐܬ̈ܘܬܐ܀ (In textu pro edito ܘܡܫܘ̈ܪܐ[?] in codice est ܘܦܫܘ̈ܪܐ, ut conjecerat Bernstein., cum scholio: “ܦܫܘ̈ܪܐ appellat eos qui interpretantur (ܕܦܫܪܝܢ) somnia, et hariolos, et tales.”","en":"Cod. 86. Syro-hex. agrees: ܐ. ܘܡܩܨ̈ܡܐ[?]܀ ܣ. ܦܪ̈ܘܫܝ[?] ܐܬ̈ܘܬܐ܀ (In the text, for the printed ܘܡܫܘ̈ܪܐ[?] the codex has ܘܦܫܘ̈ܪܐ, as Bernstein had conjectured, with the scholion: “ܦܫܘ̈ܪܐ he calls those who interpret (ܕܦܫܪܝܢ) dreams, and soothsayers, and such.”"},"1011.0.20":{"la":"Syro-hex, cum notula, quae ad utrum horum locorum pertineat incertum est: “Hic obelus (ܫܘܦܕܐ[?]) non positus erat in Hexaplis.”","en":"Syro-hex, with a short note, to which of these two places it belongs being uncertain: “This obelus (ܫܘܦܕܐ[?]) was not placed in the Hexapla.”"},"1011.1.1":{"la":"Sic Comp., Ald., Codd. 23, 42, 49, alii, Hieron., Syro-hex. Parsons. e marg. Cod. 86 exscripsit: Ἀ. ὁ κύριος εἶπεν, ἀκούσατε δὴ λόγον κυρίου. Sed revera hic codex in textu legit: ἀκ. δὴ ἃ ὁ κ. εἶπεν; in marg. autem: ἀκ. δὴ λόγον κυρίου. 6 M","en":"Thus Comp., Ald., Codd. 23, 42, 49, and others, Hieron., Syro-hex. Parsons copied from the margin of Cod. 86: Ἀ. ὁ κύριος εἶπεν, ἀκούσατε δὴ λόγον κυρίου. But in reality this codex reads in the text: ἀκ. δὴ ἃ ὁ κ. εἶπεν; and in the margin: ἀκ. δὴ λόγον κυρίου."},"1012.0.2":{"la":"Syro-hex. ܐ. ܘܡܥܫܢ̈ܐ[?]܀ ܣ. ܘܥܬܝ̈ܩܬܐ[?]܀ ܬ. ܘܫܬܐܣ̈ܐ ܕܡܢ ܩܕܝܡ܀ Ad Aq. cf. Hex. ad Psal. lxxiii. 15. Jerem. xlix. 19. (Vox Syriaca ܡܥܫܢܐ ponitur pro στερεὸς (usitatius ܥܫܝܢܐ) in Hex. ad Psal. lxxii. 4, necnon in versione N. T. Philox. passim. Ad ܕܡܢ ܩܕܝܡ cf. Jesai. xxv. 1 in Syro-hex.) Hieron.: “Pro _fortibus fundamentis terrae_, quae LXX, _et valles fundamenta terrae_, interpretati sunt, Sym. et Theod. transtulerunt, _et antiqua fundamenta terrae._","en":"Syro-hex. ܐ. ܘܡܥܫܢ̈ܐ[?]܀ ܣ. ܘܥܬܝ̈ܩܬܐ[?]܀ ܬ. ܘܫܬܐܣ̈ܐ ܕܡܢ ܩܕܝܡ܀ On Aq. cf. Hex. on Psal. lxxiii. 15. Jerem. xlix. 19. (The Syriac word ܡܥܫܢܐ is used for στερεὸς (more usually ܥܫܝܢܐ) in Hex. on Psal. lxxii. 4, and also frequently in the Philox. version of the N. T. On ܕܡܢ ܩܕܝܡ cf. Jesai. xxv. 1 in Syro-hex.) Hieron.: “For _strong foundations of the earth_, which the LXX rendered _and valleys, foundations of the earth_, Sym. and Theod. translated _and ancient foundations of the earth._"},"1012.0.3":{"la":"Hieron.","en":"Hieron."},"1012.0.4":{"la":"Syro-hex. ܣ. ܐܠܐܝܬܟܝ[?]܀ Cf. Hex. ad Jesai. vii. 13. Jerem. xii. 5.","en":"Syro-hex. ܣ. ܐܠܐܝܬܟܝ[?]܀ Cf. Hex. on Jesai. vii. 13. Jerem. xii. 5."},"1012.0.5":{"la":"Syro-hex. Copula hodie exstat in libris omnibus praeter Cod. 49.","en":"Syro-hex. The copula is extant today in all the books except Cod. 49."},"1012.0.6":{"la":"Idem: ܗܠܝܢ ܕܫܪܟܐ ܣܛܝܡ܀ Hieron.: “Ubi LXX _schoenis_, omnes ipsum Hebraicum SETTIM transtulerunt. Est autem locus in quo Balac rex Moabitarum adversum Israel congregavit exercitum, ὁμώνυμος arboribus, quae per eremum montis Sina hodie quoque gignuntur. … Unde arbitror et LXX σχῖνον interpretatos esse, hoc est, _lentiscum;_ sed paulatim librariorum errore factum esse, ut σχοῖνοι, id est, _funes_, pro σχίνοις legeretur.”","en":"The same: ܗܠܝܢ ܕܫܪܟܐ ܣܛܝܡ܀ Hieron.: “Where the LXX [have] _rushes_, all translated the Hebrew itself, SETTIM. It is a place in which Balak, king of the Moabites, gathered an army against Israel, ὁμώνυμος with the trees which even today grow throughout the desert of Mount Sinai. … Whence I think that the LXX too rendered σχῖνον, that is, _mastic-tree;_ but that gradually, by the error of copyists, it came about that σχοῖνοι, that is, _ropes_, was read for σχίνοις.”"},"1012.0.7":{"la":"Hieron.: “Pro _justitiis_, sive _justitia, misericordias_ interpretatus est Sym.”","en":"Hieron.: “For _righteousnesses_, or _righteousness_, Sym. rendered _mercies_.”"},"1012.0.8":{"la":"Syro-hex. ܐ. ܕܢܚ̈ܠܐ ܕܡܫܚܐ܀ ܣ. ܪ̈ܕܝܐ ܕܡܫܚܐ܀","en":"Syro-hex. ܐ. ܕܢܚ̈ܠܐ ܕܡܫܚܐ܀ ܣ. ܪ̈ܕܝܐ ܕܡܫܚܐ܀"},"1012.0.9":{"la":"Sic Comp. (cum ἀπηγ.), Codd. 22, 23, 51, alii, Hieron. Syro-hex. ܐܬܚܘܝ ܠܟ.","en":"Thus Comp. (with ἀπηγ.), Codd. 22, 23, 51, and others, Hieron. Syro-hex. ܐܬܚܘܝ ܠܟ."},"1012.0.10":{"la":"Syro-hex. ܐ. ܬ. ܐܬܐܡܪ ܠܟ܀ ܣ. ܐܡܪ ܠܟ܀","en":"Syro-hex. ܐ. ܬ. ܐܬܐܡܪ ܠܟ܀ ܣ. ܐܡܪ ܠܟ܀"},"1012.0.11":{"la":"Sic Codd. 22, 36, 51, alii, et Syro-hex.","en":"Thus Codd. 22, 36, 51, and others, and Syro-hex."},"1012.0.12":{"la":"Hieron.: “Verbum ESNE, quod LXX transtulerunt _paratum esse_, et nos diximus, _sollicitum ambulare_, Theod. significantius expressit: καὶ ἀσφαλίζου τοῦ πορεύεσθαι μετὰ Ἐλωαὶχ, id est, _et cave diligenter ut ambules cum Deo tuo:_ sive ut Quinta ed. transtulit, καὶ φροντίζειν, _agere_ scilicet _sollicite_, et hanc habere curam.”","en":"Hieron.: “The word ESNE, which the LXX translated _to be ready_, and we said _to walk carefully_, Theod. expressed more significantly: καὶ ἀσφαλίζου τοῦ πορεύεσθαι μετὰ Ἐλωαὶχ, that is, _and take diligent heed to walk with thy God:_ or as the Fifth ed. translated, καὶ φροντίζειν, namely, _to act carefully_, and to have this concern.”"},"1012.0.13":{"la":"Syro-hex. ܐ. ܢܩܪܐ܀ ܣ. ܢܓܥܐ܀ Cod. 86 affert: Σ. βοήσει.","en":"Syro-hex. ܐ. ܢܩܪܐ܀ ܣ. ܢܓܥܐ܀ Cod. 86 cites: Σ. βοήσει."},"1012.0.14":{"la":"Sic Codd. 23, 87*, alii, Hieron., Syro-hex.","en":"Thus Codd. 23, 87*, and others, Hieron., Syro-hex."},"1012.0.15":{"la":"Syro-hex. ܗܠܝܢ ܕܫܪܟܐ ܕ̈ܓܠܬܐ܀","en":"Syro-hex. ܗܠܝܢ ܕܫܪܟܐ ܕ̈ܓܠܬܐ܀"},"1012.0.16":{"la":"Sic Comp. (sine ἐπὶ), Ald., Codd. XII (in marg.), 68, 87* (cum ἐβασανίσω ἀφανισμῷ), 91 (cum ἀφανισμὸν), 97, alii. Hieron.: _Et ego cruciavi te perditione propter peccata tua._ Syro-hex. ܐܦ ܐܢܐ ܫܢܩܬ ܥܠܝܟ[?] ܒܚܘܣܪܢܐ ܡܛܠ ܚ̈ܛܗܐ ܕܝܠܟ.","en":"Thus Comp. (without ἐπὶ), Ald., Codd. XII (in the margin), 68, 87* (with ἐβασανίσω ἀφανισμῷ), 91 (with ἀφανισμὸν), 97, and others. Hieron.: _And I have tormented thee with destruction because of thy sins._ Syro-hex. ܐܦ ܐܢܐ ܫܢܩܬ ܥܠܝܟ[?] ܒܚܘܣܪܢܐ ܡܛܠ ܚ̈ܛܗܐ ܕܝܠܟ."},"1012.0.17":{"la":"Syro-hex. ܐ. ܐܦ ܐܢܐ ܫܪܝܬ ܠܡܡܚܐ[?] ܠܟ ܒܚܘܣܪܢܐ ܥܠ ܟܠܗܘܢ ܚ̈ܛܗܐ ܕܝܠܟ܀ ܣ. ܐܦ ܐܢܐ ܗܟܝܠ ܬܒܥܬ[?] ܠܟ ܒܚܘܣܪܢܐ ܡܛܠ ܚ̈ܛܗܐ ܕܝܠܟ܀ ܬ. ܘܡܢ ܩܕܝܡ ܐܢܐ ܐܝܬܝ ܕܩܪܝܬ ܡܚܘܬܐ ܕܝܠܟ. ܐܬܕܡܪܘ[?] ܥܠ ܟܠܗ̇ ܚܛܝܬܐ ܕܝܠܟ܀ Aquilam ducem secutus est Hieron., Hebraea vertens: _Et ego ergo coepi percutere te perditione super peccatis tuis._ “Theodotionis textum Syriacum, ab Hebraeo longe recedentem, frustra Graece vertere conatus sum.”—_Middeld._ Nos ex emendatiore apographo (nam Norberg. exscripserat: ܘܡܢ ܩܕܝܡ ܕܐܢܐ ܐܬܝܬ[?]) sensum qualemcunque, qui tamen ad Hebraea illustranda omnino nihil confert, eruimus.","en":"Syro-hex. ܐ. ܐܦ ܐܢܐ ܫܪܝܬ ܠܡܡܚܐ[?] ܠܟ ܒܚܘܣܪܢܐ ܥܠ ܟܠܗܘܢ ܚ̈ܛܗܐ ܕܝܠܟ܀ ܣ. ܐܦ ܐܢܐ ܗܟܝܠ ܬܒܥܬ[?] ܠܟ ܒܚܘܣܪܢܐ ܡܛܠ ܚ̈ܛܗܐ ܕܝܠܟ܀ ܬ. ܘܡܢ ܩܕܝܡ ܐܢܐ ܐܝܬܝ ܕܩܪܝܬ ܡܚܘܬܐ ܕܝܠܟ. ܐܬܕܡܪܘ[?] ܥܠ ܟܠܗ̇ ܚܛܝܬܐ ܕܝܠܟ܀ Hieron. followed Aquila as his guide, rendering the Hebrew: _And I therefore have begun to smite thee with destruction for thy sins._ “I have tried in vain to render into Greek the Syriac text of Theodotion, which departs far from the Hebrew.”—_Middeld._ We, from a more correct transcript (for Norberg. had copied: ܘܡܢ ܩܕܝܡ ܕܐܢܐ ܐܬܝܬ[?]), have extracted some sense or other, which however contributes nothing at all to illustrating the Hebrew."},"1012.0.18":{"la":"Sic Ald., Codd. XII (cum καὶ καταλήψῃ, καὶ ἐννεύσεις), 23, 40, 68, 86 (in marg.), alii, et Syro-hex. (om. καὶ ante καταλήψῃ). Hieron.: _Et ejiciam te in temetipsam, et apprehendes, et non salvabis;_ unde sua extudit Comp.: καὶ ἀποβαλῶ σε εἰς σεαυτὴν, καὶ καταλήψῃ, καὶ οὐ μὴ διασώσεις.","en":"Thus Ald., Codd. XII (with καὶ καταλήψῃ, καὶ ἐννεύσεις), 23, 40, 68, 86"},"1013.0.19":{"la":"Cod. 86 (cum καὶ οὐ μὴ διασωθείς). Correximus e Syro-hex., qui affert: ܐ. ܘܐܢܨܒܟ ܒܓܘ̈ܝܟ ܘ[ܠܐ] ܬܕܪܟܝ ܘܠܐ ܬܦܨܘܢ܀","en":"Cod. 86 (with καὶ οὐ μὴ διασωθείς). We have corrected it from Syro-hex., which cites: ܐ. ܘܐܢܨܒܟ ܒܓܘ̈ܝܟ ܘ[ܠܐ] ܬܕܪܟܝ ܘܠܐ ܬܦܨܘܢ܀"},"1013.0.20":{"la":"Syro-hex. ܣ. ܐܠܐ ܘܡܚܒܠ ܠܟ ܒܓܘ̈ܝܟ ܘܬܗܘܐ ܘܠܐ ܬܦܨܘܢ܀ Cod. 86 minus emendate affert: Σ. ἀλλὰ καὶ διαφθερεῖς εἰς τὰ ἐντός σου, καὶ ἥξεις, καὶ οὐ μὴ διασωθείς.","en":"Syro-hex. ܣ. ܐܠܐ ܘܡܚܒܠ ܠܟ ܒܓܘ̈ܝܟ ܘܬܗܘܐ ܘܠܐ ܬܦܨܘܢ܀ Cod. 86 cites less correctly: Σ. ἀλλὰ καὶ διαφθερεῖς εἰς τὰ ἐντός σου, καὶ ἥξεις, καὶ οὐ μὴ διασωθείς."},"1013.0.21":{"la":"Idem: ܬ. ܘܢܚܫܟ ܒܟ ܘܬܬܢܝܚܝܢ[?] ܘܠܐ ܬܬܦܨܝܢ܀ “Itaque in vulgari Alexandrinorum textu verba afferuntur ex Theodotionis recognitione.”—_Middeld._ Scilicet pro ܘܬܬܢܝܚܝܢ[?], quod in apographo suo invenit, Middeld. edidit ܘܬܬܢܓܕܝܢ[?], καὶ ἐκνεύσεις (cf. Rördam ad Jud. iv. 18), quae lectio est Codd. 22, 36, aliorum. Sed reapse in codice exaratum est, ut nos scripsimus, ܘܬܬܢܝܚܝܢ[?].","en":"The same: ܬ. ܘܢܚܫܟ ܒܟ ܘܬܬܢܝܚܝܢ[?] ܘܠܐ ܬܬܦܨܝܢ܀ “Thus in the common text of the Alexandrians words are adduced from Theodotion's recension.”—_Middeld._ That is, for ܘܬܬܢܝܚܝܢ[?], which he found in his transcript, Middeld. printed ܘܬܬܢܓܕܝܢ[?], καὶ ἐκνεύσεις (cf. Rördam on Jud. iv. 18), which is the reading of Codd. 22, 36, and others. But in fact the codex has written, as we have written, ܘܬܬܢܝܚܝܢ[?]."},"1013.0.22":{"la":"Duplex versio, καὶ ἐφύλαξας τὰ δ. Ζαμβρὶ, abest a Comp., Codd. 22, 23, 87*, aliis, et Syro-hex. Hieron.: “LXX: _Et dissipabuntur_ [וְיִשְׁתַּמֵּר] _legitima populi mei_ [עַמִּי]; pro quo nos posuimus propter sermonis consequentiam, _Et custodisti praecepta Amri_, licet et in Hebraeo scriptum sit, _Et custodita sunt praecepta Amri._”","en":"The double version, καὶ ἐφύλαξας τὰ δ. Ζαμβρὶ, is absent from Comp., Codd. 22, 23, 87*, and others, and Syro-hex. Hieron.: “LXX: _And the statutes of my people_ [עַמִּי] _shall be scattered_ [וְיִשְׁתַּמֵּר]; for which we, for the sake of the coherence of the discourse, put, _And thou hast kept the precepts of Omri_, although in the Hebrew too is written, _And the precepts of Omri have been kept._”"},"1013.0.23":{"la":"Syro-hex. ܣ. ܡܛܠ ܕܐܬܢܛܪܘ ܦܘܩܕ̈ܢܐ ܕܙܡܪܝ܀ ܬ. ܘܢܛܪܬ ܦܘܩܕ̈ܢܐ (ἔργα) ܕܐܡܪܝ܀","en":"Syro-hex. ܣ. ܡܛܠ ܕܐܬܢܛܪܘ ܦܘܩܕ̈ܢܐ ܕܙܡܪܝ܀ ܬ. ܘܢܛܪܬ ܦܘܩܕ̈ܢܐ (ἔργα) ܕܐܡܪܝ܀"},"1013.0.24":{"la":"Cod. 86, qui in textu ὅρια (sic) habet.","en":"Cod. 86, which has ὅρια (sic) in the text."},"1013.0.25":{"la":"Sic Comp., Ald., Codd. III, XII, 22 (cum αὐτοῦ), 23, 26, alii, Hieron., Syro-hex.","en":"Thus Comp., Ald., Codd. III, XII, 22 (with αὐτοῦ), 23, 26, and others, Hieron., Syro-hex."},"1013.0.26":{"la":"Hieron., Syro-hex.","en":"Hieron., Syro-hex."},"1013.1.1":{"la":"Syro-hex. (qui in textu οἴμοι bis habet): ܐ. ܣ. ܐܠܠܝ܀","en":"Syro-hex. (which has οἴμοι twice in the text): ܐ. ܣ. ܐܠܠܝ܀"},"1013.1.2":{"la":"Idem: ܣ. ܐܝܟ ܕܒܚܪ̈ܬܐ ܕܐܒܐ܀","en":"The same: ܣ. ܐܝܟ ܕܒܚܪ̈ܬܐ ܕܐܒܐ܀"},"1013.1.3":{"la":"Idem.","en":"The same."},"1013.1.4":{"la":"Sic in textu (ante οἴμοι ψ.) Ald. (praem. ἃ), Codd. 22, 36, 51, 62, 68 (ut Ald)., alii. Hieron.: _quae passa est_ [ἐπεπόνθησεν?] _anima mea. Vae mihi, anima._","en":"Thus in the text (before οἴμοι ψ.) Ald. (with ἃ prefixed), Codd. 22, 36, 51, 62, 68 (as Ald.), and others. Hieron.: _which my soul has suffered_ [ἐπεπόνθησεν?]. _Woe is me, O soul._"},"1013.1.5":{"la":"Cod. 86. Obelus est in Syro-hex., qui notat: “Hic obelus non positus est in Hexaplis.”","en":"Cod. 86. The obelus is in Syro-hex., which notes: “This obelus is not placed in the Hexapla.”"},"1013.1.6":{"la":"Sic Comp., Ald., Codd. II (ex corr.), III, XII, 22, 23, 26, alii, Hieron., Syro-hex.","en":"Thus Comp., Ald., Codd. II (corrected), III, XII, 22, 23, 26, and others, Hieron., Syro-hex."},"1013.1.7":{"la":"Syro-hex. ܐ. ܣ. ܚܣܝܐ܀","en":"Syro-hex. ܐ. ܣ. ܚܣܝܐ܀"},"1013.1.8":{"la":"Idem: ܓ. ܟܡܢܝܢ܀","en":"The same: ܓ. ܟܡܢܝܢ܀"},"1013.1.9":{"la":"Idem: ܐ. ܣ. ܨܝܕܝܢ ܒܚܪܡܐ܀","en":"The same: ܐ. ܣ. ܨܝܕܝܢ ܒܚܪܡܐ܀"},"1013.1.10":{"la":"Idem: ܣ. ܒܦܘܪܥܢܐ. ܐܘ ܗܘ ܪܒܐ ܡܡܠܠ ܪܓܬܐ[?] ܕܢܦܫܗ. 6 M 2 ܕܢܦܫܗ ܘܡܢܗ. ܘܐܝܟ ܚܟܝܡܐ ܒܡܘܣܗ.[?]","en":"The same: ܣ. ܒܦܘܪܥܢܐ. ܐܘ ܗܘ ܪܒܐ ܡܡܠܠ ܪܓܬܐ[?] ܕܢܦܫܗ."},"1014.0.11":{"la":"Syro-hex. ܐ. ܐܝܟ ܚܘܒܠܐ[?] ܀ ܣ. ܬ. ܐܝܟ ܟܘܒܐ ܀; cum scholio philologico: ܀ (λόγχη) ܚܘܒܠܐ[?] ܒܡܘܬܐ[?].","en":"Syro-hex. ܐ. ܐܝܟ ܚܘܒܠܐ[?] ܀ ܣ. ܬ. ܐܝܟ ܟܘܒܐ ܀; with a philological scholion: ܀ (λόγχη) ܚܘܒܠܐ[?] ܒܡܘܬܐ[?]."},"1014.0.12":{"la":"Sic Syro-hex., et sine obelo Ald., Codd. II, III, XII, 26, 49, alii, Hieron.","en":"Thus Syro-hex., and without obelus Ald., Codd. II, III, XII, 26, 49, and others, Hieron."},"1014.0.13":{"la":"Syro-hex. Symmacho continuat: ܗܘ ܛܒܐ ܕܝܠܗܘܢ ܐܝܟ ܟܘܒܐ. ܗܘ ܬܪܝܨܐ ܐܝܟ ܕܡܢ ܣܝܓܐ ܒܝܘܡܐ ܕܡܣܟܝܢ[?] ܠܟ. ܣܘܥܪܢܟ ܐܬܐ. ܗܫܐ ܢܗܘܐ ܒܟܝܐ ܕܝܠܗܘܢ ܀ Hieron.: “_Visitatio tua venit; nunc erit vastitas eorum,_ id est, habitatorum, sive _obsidio;_ MABUCHA enim magis πολιορκίαν et φρούρησιν, id est, _obsidionem_ et _custodiam,_ quam _vastitatem_ in Hebraeo sonat.” Quo fretus Montef. ad κλαυθμοὶ notam hexaplarem appinxit: Ἄλλος· πολιορκία. Ἄλλος· φρούρησις. Cf. Hex. ad 2 Reg. v. 24.","en":"Syro-hex. continues for Symmachus: ܗܘ ܛܒܐ ܕܝܠܗܘܢ ܐܝܟ ܟܘܒܐ. ܗܘ ܬܪܝܨܐ ܐܝܟ ܕܡܢ ܣܝܓܐ ܒܝܘܡܐ ܕܡܣܟܝܢ[?] ܠܟ. ܣܘܥܪܢܟ ܐܬܐ. ܗܫܐ ܢܗܘܐ ܒܟܝܐ ܕܝܠܗܘܢ ܀ Hieron.: “_Thy visitation has come; now shall be their devastation,_ that is, of the inhabitants, or _siege;_ for MABUCHA in the Hebrew signifies πολιορκίαν and φρούρησιν, that is, _siege_ and _guard,_ rather than _devastation._” Relying on this, Montef. attached a hexaplaric note to κλαυθμοὶ: Ἄλλος· πολιορκία. Ἄλλος· φρούρησις. Cf. Hex. on 2 Reg. v. 24."},"1014.0.14":{"la":"Cod. XII in marg.","en":"Cod. XII in the margin."},"1014.0.15":{"la":"Sic Ald. (cum ἐπισκοπεύσω), Codd. 23, 42, alii. Hieron.: _in Domino contemplabor._ Syro-hex. ܒܡܪܝܐ ܐܕܘܩ.","en":"Thus Ald. (with ἐπισκοπεύσω), Codd. 23, 42, and others. Hieron.: _in the Lord I will gaze._ Syro-hex. ܒܡܪܝܐ ܐܕܘܩ."},"1014.0.16":{"la":"Syro-hex. ܬ. ܠܘܬ ܡܪܝܐ ܐܚܘܪ ܀","en":"Syro-hex. ܬ. ܠܘܬ ܡܪܝܐ ܐܚܘܪ ܀"},"1014.0.17":{"la":"Sic Codd. XII (in marg.), 22 (cum ἐὰν καὶ π.), 23, 36 (ut 22), alii, Hieron., Syro-hex.","en":"Thus Codd. XII (in the margin), 22 (with ἐὰν καὶ π.), 23, 36 (as 22), and others, Hieron., Syro-hex."},"1014.0.18":{"la":"Cod. XII in marg.: Οἱ Ο΄. φῶς μοι. Sic in textu Codd. 23 (cum μου), 86 (in marg.), 87* (ut 23), alii.","en":"Cod. XII in the margin: Οἱ Ο΄. φῶς μοι. Thus in the text Codd. 23 (with μου), 86 (in the margin), 87* (as 23), and others."},"1014.0.19":{"la":"Syro-hex. in textu: φῶς μοι ※ Θ. φωτιεῖ μοι ↙.","en":"Syro-hex. in the text: φῶς μοι ※ Θ. φωτιεῖ μοι ↙."},"1014.0.20":{"la":"Sic Ald. (om. καὶ), Codd. III, XII, 22, 23, 26, alii, Hieron., Syro-hex. Mox σου om. Comp., Codd. III, XII, 26, 40, alii, Syro-hex.","en":"Thus Ald. (omitting καὶ), Codd. III, XII, 22, 23, 26, and others, Hieron., Syro-hex. Next, σου is omitted by Comp., Codd. III, XII, 26, 40, and others, Syro-hex."},"1014.0.21":{"la":"Hieron.: “_In die illa longe fiet lex,_ sive _praeceptum_ et _jussio,_ ut Sym. et Theod. interpretati sunt, dicentes ἐπιταγὴν et πρόσταγμα.”","en":"Hieron.: “_In that day the law shall be far removed,_ or _the precept_ and _the command,_ as Sym. and Theod. have rendered, saying ἐπιταγὴν and πρόσταγμα.”"},"1014.0.22":{"la":"Syro-hex. ܣ. ܝܘܡܐ ܕܠܡܒܢܐ ܣܝ̈ܓܝܟ. ܒܝܘܡܐ ܗܘ ܪܚܝܩ ܢܗܘܐ ܦܘܩܕܢܐ. ܝܘܡܐ ܕܝܢ ܗܘ ܀","en":"Syro-hex. ܣ. ܝܘܡܐ ܕܠܡܒܢܐ ܣܝ̈ܓܝܟ. ܒܝܘܡܐ ܗܘ ܪܚܝܩ ܢܗܘܐ ܦܘܩܕܢܐ. ܝܘܡܐ ܕܝܢ ܗܘ ܀"},"1014.0.23":{"la":"Idem: ÷ ܠܡܣܟܪܢܐ ܘܐ[?] ↙, cum scholio: “Hic obelus (ܫܘܦܕܐ[?]) non positus erat in libro Hexaplorum.” Sic sine obelo Codd. XII (in marg.), 22, 23, 36, alii, Hieron.","en":"The same: ÷ ܠܡܣܟܪܢܐ ܘܐ[?] ↙, with a scholion: “This obelus (ܫܘܦܕܐ[?]) was not placed in the book of the Hexapla.” Thus without obelus Codd. XII (in the margin), 22, 23, 36, and others, Hieron."},"1014.0.24":{"la":"Sic Syro-hex. Vox Ἀσσυρίων habetur in libris omnibus, et Hieron.","en":"Thus Syro-hex. The word Ἀσσυρίων is found in all the books, and in Hieron."},"1014.0.25":{"la":"Hieron.: “Ubi LXX interpretati sunt, _de Tyro,_ sciamus in Hebraico scriptum esse MASOR; quod verbum, si in praepositionem MA et nomen SOR dividatur, _de Tyro_ intelligitur; sin autem unus sermo sit, _munitionem_ sonat. Denique omnes περιοχὴν, καὶ περίφραγμα, καὶ πολιορκίαν, non _de Tyro,_ ut LXX, sed _munitionem_ et _ambitum muratae urbis_ transtulerunt.” Drusius περίφραγμα Symmacho vindicat, qui ad Psal. xxx. 22. [lix. 11] בְּעִיר מָצוֹר interpretatur ἐν πόλει περιπεφραγμένῃ.","en":"Hieron.: “Where the LXX have rendered _from Tyre,_ let us know that in the Hebrew is written MASOR; which word, if it be divided into the preposition MA and the noun SOR, is understood as _from Tyre;_ but if it be a single word, it signifies _fortification._ Accordingly all rendered περιοχὴν, καὶ περίφραγμα, καὶ πολιορκίαν, not _from Tyre,_ as the LXX, but _fortification_ and _the circuit of a walled city._” Drusius claims περίφραγμα for Symmachus, who on Psal. xxx. 22. [lix. 11] renders בְּעִיר מָצוֹר by ἐν πόλει περιπεφραγμένῃ."},"1014.0.26":{"la":"Syro-hex. ܐ. ܢܬܐܪܟ ܠܐ ܕܕܝܢܘܬܐ ܕܝܘܡܐ ܗܘ ܘܥܕܡܐ ܕܢܐܬܐ ܡܢ ܐܬܘܪ. ܘܡܕܝܢܬܐ ܕܡܚܣܢܬܐ.[?] ܘܡܢ ܣܚܘܪܬܐ ܡܚܣܢܬܐ ܘܥܕܡܐ ܠܢܗܪܐ ܘܝܡܐ. ܘܡܢ ܝܡܐ ܘܛܘܪܐ ܕܛܘܪܐ ܀[?] “Graecam interpretationem quantum fieri potuit verborum tenacem apposui, sed ut eam Hebraico textui quodammodo saltem adaptarem, verba ܠܐ [ante ܕܕܝܢܘܬܐ] et ܡܚܣܢܬܐ bis [post ܣܚܘܪܬܐ] non potui non in exilium ejicere. Offendit praeterea vox ܕܕܝܢܘܬܐ; nam Hebr. חֹק Aquila ἀκρίβασμα et ἀκριβασμὸς interpretari solet.”—_Middeld._ Locutio ܣܚܘܪܬܐ ܡܚܣܢܬܐ nullo modo sollicitanda videtur, quamvis vox Graeca, cujus circumscriptio est, non adeo certa sit. Si inter περιοχή et πολιορκία eligendum sit, posteriorem praetulerimus, cum πολιορκεῖν τινα Syriace sonet ܣܚܪ ܡܚܣܢܬܐ ܥܠܘܗܝ[?] 4 Reg. xvi. 4. xvii. 4; et πολιορκία ܣܚܘܪܬܐ ܕܥܠ ܡܚܣܢܬܐ in Hex. ad Psal. lxv. 11. Quod ad ܠܐ ܕܕܝܢܘܬܐ attinet, praeeunte Bernsteinio, Graece ἀκρισία posuimus, neglecto Hebraeo, quod prorsus aliter sonat. Aquilae usum recte definivit Middeld.; fieri tamen potest eum h. l. praeter morem non ἀκριβασμὸς (חֹק) sed ἀκρίβεια (חֻקָּה) posuisse, unde minutissimae lineolae omissione AKPIBCIA evadit, quod cum ἀκρισία commutare correctori proclive erat.","en":"Syro-hex. ܐ. ܢܬܐܪܟ ܠܐ ܕܕܝܢܘܬܐ ܕܝܘܡܐ ܗܘ ܘܥܕܡܐ ܕܢܐܬܐ ܡܢ ܐܬܘܪ. ܘܡܕܝܢܬܐ ܕܡܚܣܢܬܐ.[?] ܘܡܢ ܣܚܘܪܬܐ ܡܚܣܢܬܐ ܘܥܕܡܐ ܠܢܗܪܐ ܘܝܡܐ. ܘܡܢ ܝܡܐ ܘܛܘܪܐ ܕܛܘܪܐ ܀[?] “I have set down a Greek rendering as faithful to the words as was possible, but in order to adapt it at least in some measure to the Hebrew text"},"1015.0.27":{"la":"Syro-hex. ܬ. ܡܘܪܟ ܦܘܩܕܢܐ ܝܘܡܐ ܗܘ. ܘܡܕܝܢܬܐ ܕܝܠܟ ܢܐܬܝܢ ܡܢ ܐܬܘܪ. ܘܡܢ ܡܕܝܢܬܐ ܕܣܚܘܪܬܐ. ܘܡܢ ܣܚܘܪܬܐ ܥܕܡܐ ܠܡܝܐ ܕܢܗܪܐ ܘܕܝܡܐ. ܘܡܢ ܛܘܪܐ ܠܛܘܪܐ ܀[?] Pro ܣܚܘܪܬܐ Middeld., qui Aquilae περιοχὴν assignavit, συγκλεισμὸν, quod in textu Syro-hexaplari ita redditum est, posuit. Sed ܣܚܘܪܬܐ commutatum cum περιοχὴ videas Ezech. iv. 2. xii. 13. Jerem. xix. 9, et saepius; hac autem ratione tria vocabula Hieronymiana inter tres interpretes amice distributa sunt.","en":"Syro-hex. ܬ. ܡܘܪܟ ܦܘܩܕܢܐ ܝܘܡܐ ܗܘ. ܘܡܕܝܢܬܐ ܕܝܠܟ ܢܐܬܝܢ ܡܢ ܐܬܘܪ. ܘܡܢ ܡܕܝܢܬܐ ܕܣܚܘܪܬܐ. ܘܡܢ ܣܚܘܪܬܐ ܥܕܡܐ ܠܡܝܐ ܕܢܗܪܐ ܘܕܝܡܐ. ܘܡܢ ܛܘܪܐ ܠܛܘܪܐ ܀[?] For ܣܚܘܪܬܐ Middeld., who assigned περιοχὴν to Aquila, put συγκλεισμὸν, which is so rendered in the Syro-hexaplar text. But you may see ܣܚܘܪܬܐ interchanged with περιοχὴ in Ezech. iv. 2. xii. 13. Jerem. xix. 9, and often; and in this way the three words of Jerome are amicably distributed among the three translators."},"1015.0.28":{"la":"Hanc lectionem post ἕως τοῦ ὄρους inferunt Codd. II (sed expunct.), III, XII, 22, 26, 36, alii. In Cod. XII lectio textualis, καὶ ἀπὸ θαλάσσης—ἕως τοῦ ὄρους, in marginem ablegata est.","en":"This reading is inserted after ἕως τοῦ ὄρους by Codd. II (but expunged), III, XII, 22, 26, 36, and others. In Cod. XII the textual reading, καὶ ἀπὸ θαλάσσης—ἕως τοῦ ὄρους, is relegated to the margin."},"1015.0.29":{"la":"Sic Ald., Codd. XII (in marg.), 22, 23, 36, alii, Hieron., Syro-hex.","en":"Thus Ald., Codd. XII (in the margin), 22, 23, 36, and others, Hieron., Syro-hex."},"1015.0.30":{"la":"Syro-hex. ܣ. ܥܠ ܟܡܐ ܕܝܘܡܬܐ ܀","en":"Syro-hex. ܣ. ܥܠ ܟܡܐ ܕܝܘܡܬܐ ܀"},"1015.0.31":{"la":"Sic Comp., Ald., Codd. XII, 22, 23, 36, alii, Hieron., Syro-hex.","en":"Thus Comp., Ald., Codd. XII, 22, 23, 36, and others, Hieron., Syro-hex."},"1015.0.32":{"la":"Syro-hex.","en":"Syro-hex."},"1015.0.33":{"la":"Sic Cod. 86 in marg. sine nom. Syro-hex. ܣ. ܐܝܟ[?] ܡܬܓܪܓܪܢ[?] ܥܠ ܐܪܥܐ ܀ (Pro ܡܬܓܪܓܪܢ[?] Norberg. perperam exscripsit ܡܬܓܪܓܪܐ[?].)","en":"Thus Cod. 86 in the margin without name. Syro-hex. ܣ. ܐܝܟ[?] ܡܬܓܪܓܪܢ[?] ܥܠ ܐܪܥܐ ܀ (For ܡܬܓܪܓܪܢ[?] Norberg wrongly transcribed ܡܬܓܪܓܪܐ[?].)"},"1015.0.34":{"la":"Syro-hex. ܣ. ܠܫܪܟܢܐ ܀","en":"Syro-hex. ܣ. ܠܫܪܟܢܐ ܀"},"1015.0.35":{"la":"Sic Ald., Codd. XII (in marg.), 68, 91, alii. Ambigue Syro-hex. ܠܐ ܐܚܕ.","en":"Thus Ald., Codd. XII (in the margin), 68, 91, and others. Ambiguously Syro-hex. ܠܐ ܐܚܕ."},"1015.0.36":{"la":"Cod. 86. Cum ἐκαρτέρησεν intransitivum sit, fortasse reponendum ἐκράτησεν.","en":"Cod. 86. Since ἐκαρτέρησεν is intransitive, perhaps ἐκράτησεν should be restored."},"1015.0.37":{"la":"Hieron.: “Pro _ultra_ Sym. transtulit _in sempiternum,_ Theod. _in finem,_ LXX et Quinta ed. _in testimonium._” Cod. 86 affert: Θ. εἰς τέλος. Syro-hex.: Θ. ἕως τέλους (ܥܕܡܐ ܠܚܪܬܐ). Σ. εἰς ἀεί (ܐܡܝܢܐܝܬ). Nobil. ex Hesychio affert: Οἱ λοιποί· εἰς ἀεί.","en":"Hieron.: “For _further_ Sym. rendered _for ever,_ Theod. _to the end,_ the LXX and the Fifth ed. _for a testimony._” Cod. 86 cites: Θ. εἰς τέλος. Syro-hex.: Θ. ἕως τέλους (ܥܕܡܐ ܠܚܪܬܐ). Σ. εἰς ἀεί (ܐܡܝܢܐܝܬ). Nobil. cites from Hesychius: Οἱ λοιποί· εἰς ἀεί."},"1015.0.38":{"la":"Sic Codd. III, XII, 26, 49, alii, et Syro-hex. in textu. Idem in marg.: “In exemplari Eusebiano (ܗܘ̇ ܕܐܘܣܒܝܣ) καὶ ἀπορριφήσονται.”","en":"Thus Codd. III, XII, 26, 49, and others, and Syro-hex. in the text. The same in the margin: “In the Eusebian copy (ܗܘ̇ ܕܐܘܣܒܝܣ) καὶ ἀπορριφήσονται.”"},"1015.0.39":{"la":"Syro-hex. ܐ. ܣ. ܬ. ܬܬܠ ܀ Sic in textu Codd. 22, 23, 36, alii.","en":"Syro-hex. ܐ. ܣ. ܬ. ܬܬܠ ܀ Thus in the text Codd. 22, 23, 36, and others."},"1015.0.40":{"la":"Syro-hex. in textu: ܐܝܟ ܝܘܡܬܐ ܕܡܢ ܩܘܕܡܐ ܀; in marg. autem: ܐ. ܒܕܡܘܬ[?] ܗܠܝܢ ܕܫܒܥܝܢ ܡܢ ܩܘܕܡܐ ܀ ܣ. ܡܢ ܝܘܡܬܐ ܥܬܝܩܐ ܀ ܬ. ܗܠܝܢ ܕܡܢ ܩܕܡ ܀","en":"Syro-hex. in the text: ܐܝܟ ܝܘܡܬܐ ܕܡܢ ܩܘܕܡܐ ܀; but in the margin: ܐ. ܒܕܡܘܬ[?] ܗܠܝܢ ܕܫܒܥܝܢ ܡܢ ܩܘܕܡܐ ܀ ܣ. ܡܢ ܝܘܡܬܐ ܥܬܝܩܐ ܀ ܬ. ܗܠܝܢ ܕܡܢ ܩܕܡ ܀"}}};
